INSERT INTO categories (key, label_fr, label_en, note_fr, note_en, image, hidden, sort_order) VALUES ('absolues', 'Les Absolues Précieuses', 'Precious Absolutes', 'Nectars floraux d''une opulence absolue, extraits pour la haute parfumerie de niche.', 'Absolutely opulent floral nectars, extracted for high-end niche perfumery.', '/images/categories/absolues.jpg', 0, 0);
INSERT INTO categories (key, label_fr, label_en, note_fr, note_en, image, hidden, sort_order) VALUES ('concretes', 'Les Concrètes Raw', 'Raw Concretes', 'Ciments végétaux purs et cireux, capturant l''âme primitive de la plante fraîche.', 'Pure waxy botanical concretes capturing the raw soul of the fresh plant.', '/images/categories/concretes.jpg', 0, 1);
INSERT INTO categories (key, label_fr, label_en, note_fr, note_en, image, hidden, sort_order) VALUES ('huiles-essentielles', 'Les Huiles Essentielles', 'Essential Oils', 'Élixirs aromatiques d''une clarté cristalline, distillés avec un savoir-faire traditionnel.', 'Crystal-clear aromatic elixirs, distilled with traditional expertise.', '/images/categories/huiles-essentielles.jpg', 0, 2);
INSERT INTO categories (key, label_fr, label_en, note_fr, note_en, image, hidden, sort_order) VALUES ('huiles-porteuses', 'Les Huiles Suprêmes Porteuses / Carrier Oils', 'Supreme Carrier Oils', 'Trésors lipidiques dorés et ultra-filtrés, servant de base active royale pour les soins de luxe et attars.', 'Golden, ultra-filtered lipid treasures serving as a royal active base for luxury skincare and attars.', '/images/categories/huiles-porteuses.jpg', 0, 3);
INSERT INTO categories (key, label_fr, label_en, note_fr, note_en, image, hidden, sort_order) VALUES ('herbes-epices', 'Herbes & Épices', 'Herbs & Spices', 'Bientôt disponible.', 'Coming soon.', '/images/categories/herbes-epices.jpg', 1, 4);
INSERT INTO products (sku, category_key, name_fr, name_en, subtitle_fr, subtitle_en, inci, cas, origin, extraction_method_fr, extraction_method_en, short_description_fr, short_description_en, image, images, description_fr, specifications_fr, organoleptic_fr, regulatory_fr, quality_fr, confidentiality_fr, sort_order) VALUES ('BNABS001', 'absolues', 'Absolue de Cassie d''Égypte', 'Egyptian Cassie Absolute', 'Le Sphinx Doré – L''Énigme Florale Cuirée Intrépide', 'The Golden Sphinx – The Bold Leathery Floral Enigma', 'Acacia Farnesiana Flower Extract', '8023-82-3 / 89957-43-7', 'Égypte', 'Extraction Secondaire à l''Éthanol', 'Secondary Ethanol Extraction', 'Mûrie sous le soleil d''hiver des plaines d''Égypte, notre Absolue de Cassie de Bostan Naturals est un trésor d''une rareté absolue, hautement prisé par la haute parfumerie de niche. Cet élixir mystique, extrait des fleurs d''Acacia farnesiana, déploie une signature olfactive d''une complexité phénoménale : notes de tête florales denses et chaleureuses, cœur boisé, herbacé et balsamique, fond puissamment cuiré, animal et velouté d''une ténacité souveraine.', 'Ripened under Egypt''s winter sun, our Bostan Naturals Cassie Absolute is a treasure of absolute rarity, highly prized by high-end niche perfumery. Extracted from Acacia farnesiana flowers, this mystical elixir unfolds a phenomenally complex olfactory signature: dense, warm floral top notes, a woody, herbaceous, balsamic heart, and a powerfully leathery, animalic, velvety base of sovereign tenacity.', '/images/categories/absolues.jpg', '[]', 'ABSOLUE DE CASSIE D''ÉGYPTE
Le Sphinx Doré – L''Énigme Florale Cuirée Intrépide

Mûrie sous le soleil d''hiver des plaines d''Égypte, notre Absolue de Cassie de Bostan Naturals est un trésor d''une rareté absolue, hautement prisé par la haute parfumerie de niche. Cet élixir mystique, extrait des fleurs d''Acacia farnesiana, déploie une signature olfactive d''une complexité phénoménale. Il s''ouvre sur des notes de tête florales denses et chaleureuses, rehaussées de facettes poudrées et miellées qui rappellent le mimosa sauvage. Rapidement, son cœur révèle une profondeur boisée, herbacée et balsamique, avant de s''épanouir sur un fond puissamment cuiré, animal et velouté d''une ténacité souveraine. Un ingrédient de caractère indispensable pour structurer, mystifier et apporter un relief charnel incomparable aux compositions orientales, florales et cuirs de prestige.', '["Nom INCI : Acacia Farnesiana Flower Extract","Numéro CAS : 8023-82-3 / 89957-43-7","Code SKU : BNABS001","Source Botanique : Acacia farnesiana (L.) Willd. (Fabaceae)","Origine : Égypte (100% Pure & Naturelle)","Procédé : Extraction secondaire à l''éthanol à partir de la concrète de première extraction"]', '["Aspect : Liquide visqueux fluide à semi-liquide selon la température","Couleur : Jaune ambré foncé à brun verdâtre profond","Odeur : Florale dense, poudrée, intensément miellée, aux facettes boisées et cuirées masquées d''un sillage animal persistant","Indice de Réfraction @ 20°C : 1.4950 – 1.5200","Densité Relative @ 20°C : 0.9500 – 0.9900","Solubilité : Parfaitement soluble dans l''éthanol fort et les solvants de parfumerie"]', 'Sécurité Moléculaire & Conformité REACH
Chez Bostan Naturals, la rigueur technique valide votre liberté créative. Notre Absolue de Cassie fait l''objet d''analyses des solvants résiduels lorsque cela est applicable au produit et à son procédé d''extraction. Ce produit haut de gamme est conforme aux exigences et restrictions applicables de l''IFRA pour l''utilisation prévue de la matière en parfumerie (la dernière mise à jour en vigueur) et s''aligne pleinement avec les exigences du règlement européen REACH, assurant une intégration sécurisée dans les formulations de Catégorie 4 (Fine Fragrances).', 'Standard de Production : Processus de filtration à froid ultra-précis garantissant l''élimination des cires insolubles sans altérer les molécules olfactives nobles, selon les plus strictes directives de management de la qualité.
Authenticité Géographique : 100% Cassie d''Égypte issue de cultures locales rigoureusement contrôlées.
Contrôle Laboratoire : Les analyses sont réalisées selon les exigences du produit et du lot, auprès de laboratoires appropriés lorsque nécessaire.
Conditionnement de Transport Conforme aux Exigences Applicables : Conditionné en flacons d''aluminium professionnels étanches pour bloquer l''air et la lumière, préservant ainsi la viscosité naturelle et le profil aromatique. Chaque unité est munie d''une étiquette technique standardisée de traçabilité (Sceau Bostan Naturals, SKU, Batch et Mentions légales).', 'La Garantie du Secret Commercial de Vos Formules :
Afin de protéger vos intérêts commerciaux et de masquer l''origine de vos matières premières stratégiques, Bostan Naturals édite l''intégralité des rapports d''analyses techniques exclusivement sous sa propre marque :
1. Télécharger la Fiche Technique de l''Absolue (TDS) liée au SKU BNABS001
2. Télécharger le Certificat d''Analyse (COA) Spécifique au Lot
3. Télécharger la Fiche de Données de Sécurité (FDS / MSDS) Conforme UE', 0);
INSERT INTO products (sku, category_key, name_fr, name_en, subtitle_fr, subtitle_en, inci, cas, origin, extraction_method_fr, extraction_method_en, short_description_fr, short_description_en, image, images, description_fr, specifications_fr, organoleptic_fr, regulatory_fr, quality_fr, confidentiality_fr, sort_order) VALUES ('BNABS002', 'absolues', 'Absolue de Jasmine Grandiflorum d''Égypte', 'Egyptian Jasmine Grandiflorum Absolute', 'La Reine du Nil – L''Opulence Florale Blanche Indolique Absolue', 'The Queen of the Nile – The Absolute White Floral Indolic Opulence', 'Jasminum Grandiflorum Flower Extract', '8022-43-1 / 84776-64-7', 'Égypte', 'Extraction secondaire à l''alcool éthylique à partir de la concrète de jasmin', 'Secondary Ethyl Alcohol Extraction from Jasmine Concrete', 'Récoltée à l''aube dans les champs fertiles du delta du Nil, notre Absolue de Jasmin Grandiflorum de Bostan Naturals incarne le prestige absolu de la haute parfumerie mondiale. Cet élixir mythique déploie une signature olfactive d''une sensualité radieuse et addictive. Il s''ouvre sur une envolée florale blanche intense, à la fois lumineuse, fruitée (nuances de banane mûre et de confiture d''abricot) et chaleureuse. Son cœur révèle une richesse indolique profonde, noble et voluptueuse, avant de s''épanouir sur un fond balsamique-animal, gras et d''une persistance magnétique incomparable. Un joyau architectural indispensable pour infuser de l''éclat, du volume, de la rondeur et une élégance charnelle intemporelle aux plus grandes créations Florales, Orientales et Chyprées.', 'Harvested at dawn in the fertile fields of the Nile Delta, our Bostan Naturals Jasmine Grandiflorum Absolute embodies the absolute prestige of the world''s fine perfumery. This mythical elixir unfolds an olfactory signature of radiant, addictive sensuality. It opens with an intense white floral burst, at once luminous, fruity (hints of ripe banana and apricot jam) and warm. Its heart reveals a deep, noble and voluptuous indolic richness, before blossoming into a balsamic-animalic, rich base of incomparable magnetic persistence. An indispensable architectural gem for infusing radiance, volume, roundness and timeless carnal elegance into the greatest Floral, Oriental and Chypre creations.', '/images/categories/absolues.jpg', '[]', 'ABSOLUE DE JASMINE GRANDIFLORUM D''ÉGYPTE
La Reine du Nil – L''Opulence Florale Blanche Indolique Absolue

Récoltée à l''aube dans les champs fertiles du delta du Nil, notre Absolue de Jasmin Grandiflorum de Bostan Naturals incarne le prestige absolu de la haute parfumerie mondiale. Cet élixir mythique déploie une signature olfactive d''une sensualité radieuse et addictive. Il s''ouvre sur une envolée florale blanche intense, à la fois lumineuse, fruitée (nuances de banane mûre et de confiture d''abricot) et chaleureuse. Son cœur révèle une richesse indolique profonde, noble et voluptueuse, avant de s''épanouir sur un fond balsamique-animal, gras et d''une persistance magnétique incomparable. Un joyau architectural indispensable pour infuser de l''éclat, du volume, de la rondeur et une élégance charnelle intemporelle aux plus grandes créations Florales, Orientales et Chyprées.', '["Nom INCI : Jasminum Grandiflorum Flower Extract","Numéro CAS : 8022-43-1 / 84776-64-7","Code SKU : BNABS002","Source Botanique : Jasminum grandiflorum L. (Oleaceae)","Origine : Égypte (100% Pure, Naturelle & Non altérée)","Procédé : Extraction secondaire à l''alcool éthylique à partir de la concrète de jasmin"]', '["Aspect : Liquide mobile à fluide, limpide.","Couleur : Brun orangé foncé à rouge ambré profond.","Odeur : Intensément florale blanche, chaude, riche, fruitée-miellée, avec des sous-tons animaux et indoliques nobles caractéristiques du jasmin égyptien.","Indice de Réfraction @ 20°C : 1.4880 – 1.5150","Densité Relative @ 20°C : 0.9500 – 0.9850","Solubilité : Parfaitement soluble dans l''alcool éthylique et les huiles de support."]', 'Sécurité Moléculaire & Certification IFRA
Chez Bostan Naturals, l''excellence technique protège votre liberté créative. Notre Absolue de Jasmin Grandiflorum est conforme aux exigences et restrictions applicables de l''IFRA pour l''utilisation prévue de la matière en parfumerie (la dernière mise à jour en vigueur) et répond pleinement aux critères de la réglementation européenne REACH. Pour chaque lot isolé, nous mesurons et traçons de manière dynamique les teneurs naturelles en molécules restreintes (notamment le benzoate de benzyle, le linalol et l''alcool benzylique) afin d''assurer une traçabilité irréprochable et de simplifier vos démarches de validation toxicologique en Catégorie 4.', 'Standard de Production : Séparation méticuleuse des cires par glaçage sous vide à température contrôlée pour préserver l''équilibre natif des esters volatils (acétate de benzyle), selon les plus strictes directives de management de la qualité.
Authenticité Territoriale : 100% Jasmin d''Égypte récolté à la main par des filières durables.
Contrôle Laboratoire : Les analyses sont réalisées selon les exigences du produit et du lot, auprès de laboratoires appropriés lorsque nécessaire.
Conditionnement de Transport Conforme aux Exigences Applicables : Expédié dans des flacons en aluminium blindés et scellés, protégeant le produit de l''oxydation thermique et garantissant la sécurité lors du transport international. Chaque unité est munie d''une étiquette technique standardisée de traçabilité (Sceau Bostan Naturals, SKU, Batch et Mentions légales).', 'Votre Traçabilité Commerciale sous Sceau de Confidentialité :
Pour préserver l''intégrité absolue de vos formules et garantir le secret commercial le plus strict concernant vos sources d''approvisionnement, chaque lot de Bostan Naturals est accompagné de son dossier réglementaire dédié, édité exclusivement sous notre nom de marque :
1. Télécharger le Profil Chromatographique (Empreinte GC-MS d''authenticité) lié au SKU BNABS002
2. Télécharger le Certificat d''Analyse (COA) Spécifique au Lot
3. Télécharger la Fiche de Données de Sécurité (FDS / MSDS) Conforme UE', 1);
INSERT INTO products (sku, category_key, name_fr, name_en, subtitle_fr, subtitle_en, inci, cas, origin, extraction_method_fr, extraction_method_en, short_description_fr, short_description_en, image, images, description_fr, specifications_fr, organoleptic_fr, regulatory_fr, quality_fr, confidentiality_fr, sort_order) VALUES ('BNABS003', 'absolues', 'Absolue de Fleur d''Oranger d''Égypte', 'Egyptian Orange Blossom Absolute', 'Le Crépuscule d''Or – L''Opulence Florale Animale Sacrée', 'The Golden Dusk – The Sacred Animalic Floral Opulence', 'Citrus Aurantium Amara Flower Extract', '8030-28-2 / 72968-50-4', 'Égypte', 'Extraction secondaire à l''alcool éthylique à partir de la concrète de fleur d''oranger', 'Secondary Ethyl Alcohol Extraction from Orange Blossom Concrete', 'Extraite des pétales immaculés de Citrus aurantium var. amara récoltés au printemps en Égypte, notre Absolue de Fleur d''Oranger de Bostan Naturals est le paroxysme du luxe olfactif pour la parfumerie de niche. Contrairement au Néroli aérien, l''Absolue révèle la face sombre, charnelle et hypnotique de la fleur. Elle déploie une signature olfactive monumentale : une attaque florale dense, sucrée et miellée, qui plonge dans un cœur intensément cireux, vert-amande et indolique, avant de s''ancrer sur un fond animal, chaud et balsamique d''une ténacité obsessionnelle. Un ingrédient architectural d''une puissance rare, indispensable pour insuffler de la profondeur, du mystère, de la rondeur et une vibration charnelle addictive aux structures Florales et Orientales.', 'Extracted from the immaculate petals of Citrus aurantium var. amara harvested in spring in Egypt, our Bostan Naturals Orange Blossom Absolute is the pinnacle of olfactory luxury for niche perfumery. Unlike the airborne Neroli, the Absolute reveals the dark, carnal and hypnotic face of the flower. It unfolds a monumental olfactory signature: a dense, sweet, honeyed floral opening, plunging into an intensely waxy, green-almond and indolic heart, before anchoring on an animalic, warm and balsamic base of obsessive tenacity. An architectural ingredient of rare power, indispensable for infusing depth, mystery, roundness and an addictive carnal vibration into Floral and Oriental structures.', '/images/categories/absolues.jpg', '[]', 'ABSOLUE DE FLEUR D''ORANGER D''ÉGYPTE
Le Crépuscule d''Or – L''Opulence Florale Animale Sacrée

Extraite des pétales immaculés de Citrus aurantium var. amara récoltés au printemps en Égypte, notre Absolue de Fleur d''Oranger de Bostan Naturals est le paroxysme du luxe olfactif pour la parfumerie de niche. Contrairement au Néroli aérien, l''Absolue révèle la face sombre, charnelle et hypnotique de la fleur. Elle déploie une signature olfactive monumentale : une attaque florale dense, sucrée et miellée, qui plonge dans un cœur intensément cireux, vert-amande et indolique, avant de s''ancrer sur un fond animal, chaud et balsamique d''une ténacité obsessionnelle. Un ingrédient architectural d''une puissance rare, indispensable pour insuffler de la profondeur, du mystère, de la rondeur et une vibration charnelle addictive aux structures Florales et Orientales.', '["Nom INCI : Citrus Aurantium Amara Flower Extract","Numéro CAS : 8030-28-2 / 72968-50-4","Code SKU : BNABS003","Source Botanique : Citrus aurantium var. amara L. (Rutaceae)","Origine : Égypte (100% Pure, Naturelle & Intègre)","Procédé : Extraction secondaire à l''alcool éthylique à partir de la concrète de fleur d''oranger"]', '["Aspect : Liquide visqueux mobile à pâteux selon la température.","Couleur : Brun ambré foncé à rouge orangé profond.","Odeur : Puissante, florale-orangée intense, lourde, miellée, aux facettes animales, indoliques et vertes très prononcées.","Indice de Réfraction @ 20°C : 1.4900 – 1.5200","Densité Relative @ 20°C : 0.9500 – 0.9930","Solubilité : Parfaitement soluble dans l''alcool éthylique fort et les huiles de parfum."]', 'Conformité Totale aux Normes Internationales & REACH
Chez Bostan Naturals, la rigueur technique sécurise vos créations. Notre Absolue de Fleur d''Oranger est conforme aux exigences et restrictions applicables de l''IFRA pour l''utilisation prévue de la matière en parfumerie (la dernière mise à jour en vigueur) et répond pleinement aux exigences de la réglementation européenne REACH. Pour chaque expédition, nous suivons de manière dynamique les teneurs exactes en allergènes naturels volatils (notamment le linalol, le géraniol, le farnésol et l''anthranilate de méthyle) afin de garantir une sécurité dermatologique absolue et de faciliter l''évaluation réglementaire et la formulation de vos formules en Catégorie 4.', 'Standard de Production : Filtration à froid stricte pour éliminer les cires lourdes insolubles tout en protégeant le profil aromatique natif, selon les plus strictes directives de management de la qualité.
Traçabilité Botanique Royale : Fleurs récoltées exclusivement auprès de nos filières agricoles locales et écoresponsables.
Contrôle Laboratoire : Les analyses sont réalisées selon les exigences du produit et du lot, auprès de laboratoires appropriés lorsque nécessaire.
Conditionnement de Transport Conforme aux Exigences Applicables : Livré en flacons d''aluminium professionnels étanches pour préserver la viscosité naturelle et protéger le profil aromatique de l''air et de la lumière. Chaque unité est munie d''une étiquette technique standardisée de traçabilité (Sceau Bostan Naturals, SKU, Batch et Mentions légales).', 'La Garantie du Secret Commercial de Vos Formules :
Afin de protéger vos intérêts commerciaux et de masquer l''origine de vos matières premières stratégiques, Bostan Naturals édite l''intégralité des rapports d''analyses techniques exclusivement sous sa propre marque :
1. Télécharger la Fiche Technique de l''Absolue (TDS) liée au SKU BNABS003
2. Télécharger le Certificat d''Analyse (COA) Spécifique au Lot
3. Télécharger la Fiche de Données de Sécurité (FDS / MSDS) Conforme UE', 2);
INSERT INTO products (sku, category_key, name_fr, name_en, subtitle_fr, subtitle_en, inci, cas, origin, extraction_method_fr, extraction_method_en, short_description_fr, short_description_en, image, images, description_fr, specifications_fr, organoleptic_fr, regulatory_fr, quality_fr, confidentiality_fr, sort_order) VALUES ('BNABS004', 'absolues', 'Absolue de Caroube d''Égypte', 'Egyptian Carob Absolute', 'Le Nectar d''Alexandrie – L''Avant-Garde Gourmande et Ambrée', 'The Nectar of Alexandria – The Gourmand and Amber Avant-Garde', 'Ceratonia Siliqua Fruit Extract', '84961-45-5 / 9000-40-2', 'Égypte', 'Extraction secondaire à l''éthanol à chaud à partir de la concrète de caroube primaire', 'Secondary Hot Ethanol Extraction from Primary Carob Concrete', 'Issue des gousses riches en sucres complexes de Ceratonia siliqua mûries sous la chaleur sèche égyptienne, notre Absolue de Caroube de Bostan Naturals est une matière première d''avant-garde, pilier secret de la parfumerie de niche contemporaine. Cet élixir d''une richesse inouïe déploie une signature olfactive profondément addictive et facettée. Il s''ouvre sur des notes chaleureuses de sucre caramélisé et de chicorée torréfiée, révélant un cœur velouté de cacao ambré, de fruits secs et de gousse de vanille noire, avant de s''épanouir sur un fond balsamique et boisé-sombre d''une ténacité magistrale. Un ingrédient architectural de choix, indispensable pour infuser de la texture, du relief et une sensualité gourmande non collante et hautement sophistiquée aux compositions ambrées, boisées et cuirs de luxe.', 'Issued from the pods rich in complex sugars of Ceratonia siliqua ripened under the dry Egyptian heat, our Bostan Naturals Carob Absolute is an avant-garde raw material, a secret pillar of contemporary niche perfumery. This elixir of unheard-of richness unfolds a deeply addictive and multi-faceted olfactory signature. It opens with warm notes of caramelized sugar and roasted chicory, revealing a velvety heart of amber cocoa, dried fruits and black vanilla pod, before blossoming into a balsamic and dark-woody base of masterful tenacity. An architectural ingredient of choice, indispensable for infusing texture, relief and a non-sticky, highly sophisticated gourmand sensuality into amber, woody and luxury leather compositions.', '/images/categories/absolues.jpg', '[]', 'ABSOLUE DE CAROUBE D''ÉGYPTE
Le Nectar d''Alexandrie – L''Avant-Garde Gourmande et Ambrée

Issue des gousses riches en sucres complexes de Ceratonia siliqua mûries sous la chaleur sèche égyptienne, notre Absolue de Caroube de Bostan Naturals est une matière première d''avant-garde, pilier secret de la parfumerie de niche contemporaine. Cet élixir d''une richesse inouïe déploie une signature olfactive profondément addictive et facettée. Il s''ouvre sur des notes chaleureuses de sucre caramélisé et de chicorée torréfiée, révélant un cœur velouté de cacao ambré, de fruits secs et de gousse de vanille noire, avant de s''épanouir sur un fond balsamique et boisé-sombre d''une ténacité magistrale. Un ingrédient architectural de choix, indispensable pour infuser de la texture, du relief et une sensualité gourmande non collante et hautement sophistiquée aux compositions ambrées, boisées et cuirs de luxe.', '["Nom INCI : Ceratonia Siliqua Fruit Extract","Numéro CAS : 84961-45-5 / 9000-40-2","Code SKU : BNABS004","Source Botanique : Ceratonia siliqua L. (Fabaceae)","Origine : Égypte (100% Pure, Naturelle & Non altérée)","Procédé : Extraction secondaire à l''éthanol à chaud à partir de la concrète de caroube primaire"]', '["Aspect : Liquide visqueux épais à semi-solide à température ambiante (nécessite un léger chauffage modéré).","Couleur : Brun chocolat très foncé à noir ambré opaque.","Odeur : Puissamment balsamique, chaude, de caramel brûlé, de chicorée, de fruits secs et de tabac de luxe.","Indice de Réfraction @ 20°C : Non applicable (produit trop sombre) ou 1.4900 – 1.5200 après dilution technique.","Solubilité : Insoluble dans l''eau, parfaitement soluble dans l''éthanol et les mélanges de solvants de parfumerie."]', 'Protection Moléculaire & Conformité REACH
Chez Bostan Naturals, l''excellence réglementaire valide votre créativité. Notre Absolue de Caroube fait l''objet de contrôles et d''analyses qualité adaptés à la nature du produit, incluant des analyses des solvants résiduels lorsque cela est applicable. Elle est conforme aux exigences et restrictions applicables de l''IFRA pour l''utilisation prévue de la matière en parfumerie (la dernière mise à jour en vigueur) et répond scrupuleusement au protocole REACH de l''Union Européenne, assurant une parfaite sécurité pour les développements parfumés en Catégorie 4 (Fine Fragrances).', 'Standard de Production : Purification mécanique et thermique standardisée pour garantir un profil organoleptique constant sans fluctuations de lots, selon les plus strictes directives de management de la qualité.
Authenticité Géographique : 100% Caroube d''Égypte issue de cultures locales contrôlées.
Contrôle Laboratoire : Les analyses sont réalisées selon les exigences du produit et du lot, auprès de laboratoires appropriés lorsque nécessaire.
Conditionnement de Transport Conforme aux Exigences Applicables : Expédié dans des flacons en aluminium professionnels épais pour préserver la viscosité naturelle et protéger le profil aromatique de la lumière et de l''air. Chaque unité est munie d''une étiquette technique standardisée de traçabilité (Sceau Bostan Naturals, SKU, Batch et Mentions légales).', 'La Garantie du Secret Commercial de Vos Formules :
Afin de protéger vos intérêts commerciaux et de masquer l''origine de vos matières premières stratégiques, Bostan Naturals édite l''intégralité des rapports d''analyses techniques exclusivement sous sa propre marque :
1. Télécharger la Fiche Technique de l''Absolue (TDS) liée au SKU BNABS004
2. Télécharger le Certificat d''Analyse (COA) Spécifique au Lot
3. Télécharger la Fiche de Données de Sécurité (FDS / MSDS) Conforme UE', 3);
INSERT INTO products (sku, category_key, name_fr, name_en, subtitle_fr, subtitle_en, inci, cas, origin, extraction_method_fr, extraction_method_en, short_description_fr, short_description_en, image, images, description_fr, specifications_fr, organoleptic_fr, regulatory_fr, quality_fr, confidentiality_fr, sort_order) VALUES ('BNABS005', 'absolues', 'Absolue de Géranium d''Égypte', 'Egyptian Geranium Absolute', 'Le Sceptre Vert – La Vibration Rosée Herbacée Lourde', 'The Green Sceptre – The Heavy Herbaceous Rosy Vibration', 'Pelargonium Graveolens Extract', '90082-51-2 / 8000-46-2', 'Égypte', 'Extraction secondaire à l''alcool éthylique à partir de la concrète de géranium fraîche', 'Secondary Ethyl Alcohol Extraction from Fresh Geranium Concrete', 'Extraite des parties aériennes fraîches de Pelargonium graveolens cultivé sur nos domaines en Égypte, notre Absolue de Géranium de Bostan Naturals est une matière première d''une puissance et d''une ténacité magistrales. Contrairement à l''huile essentielle distillée, l''Absolue capture les cires cuticulaires lourdes et les pigments complexes de la feuille. Elle déploie une signature olfactive d''une richesse inouïe : une envolée verte, herbeuse coupante et subtilement menthée, qui plonge dans un cœur floral intensément rosé, velouté, rehaussé de notes de litchi et d''un fond balsamique-terreux d''une élégance rare. Un ingrédient architectural indispensable pour insuffler du relief, de la texture, du naturel et une tenue phénoménale aux structures Florales, Fougères et Chyprées de niche.', 'Extracted from the fresh aerial parts of Pelargonium graveolens cultivated on our estates in Egypt, our Bostan Naturals Geranium Absolute is a raw material of masterful power and tenacity. Unlike the distilled essential oil, the Absolute captures the heavy cuticular waxes and complex pigments of the leaf. It unfolds an olfactory signature of unheard-of richness: a green, sharp grassy and subtly minty opening, plunging into an intensely rosy, velvety floral heart, enhanced by lychee notes and a balsamic-earthy base of rare elegance. An indispensable architectural ingredient for infusing relief, texture, naturalness and phenomenal tenacity into niche Floral, Fougère and Chypre structures.', '/images/categories/absolues.jpg', '[]', 'ABSOLUE DE GÉRANIUM D''ÉGYPTE
Le Sceptre Vert – La Vibration Rosée Herbacée Lourde

Extraite des parties aériennes fraîches de Pelargonium graveolens cultivé sur nos domaines en Égypte, notre Absolue de Géranium de Bostan Naturals est une matière première d''une puissance et d''une ténacité magistrales. Contrairement à l''huile essentielle distillée, l''Absolue capture les cires cuticulaires lourdes et les pigments complexes de la feuille. Elle déploie une signature olfactive d''une richesse inouïe : une envolée verte, herbeuse coupante et subtilement menthée, qui plonge dans un cœur floral intensément rosé, velouté, rehaussé de notes de litchi et d''un fond balsamique-terreux d''une élégance rare. Un ingrédient architectural indispensable pour insuffler du relief, de la texture, du naturel et une tenue phénoménale aux structures Florales, Fougères et Chyprées de niche.', '["Nom INCI : Pelargonium Graveolens Extract","Numéro CAS : 90082-51-2 / 8000-46-2","Code SKU : BNABS005","Source Botanique : Pelargonium graveolens L''Hér. (Geraniaceae)","Origine : Égypte (100% Pure & Naturelle)","Procédé : Extraction secondaire à l''alcool éthylique à partir de la concrète de géranium fraîche"]', '["Aspect : Liquide mobile à légèrement visqueux.","Couleur : Vert olive foncé à vert émeraude profond.","Odeur : Puissante, florale-rosée intense, fortement herbacée, cireuse avec des facettes terreuses et menthées prononcées caractéristiques du géranium égyptien.","Indice de Réfraction @ 20°C : 1.4650 – 1.4950","Densité Relative @ 20°C : 0.9200 – 0.9550","Solubilité : Parfaitement soluble dans l''alcool éthylique fort et les huiles."]', 'Conformité Totale & Traçabilité Européenne
Chez Bostan Naturals, la perfection technique est garantie. Notre Absolue de Géranium Égyptien est conforme aux exigences et restrictions applicables de l''IFRA pour l''utilisation prévue de la matière en parfumerie (la dernière mise à jour en vigueur) et répond scrupuleusement au protocole européen REACH. Nous suivons de près les concentrations naturelles d''allergènes volatils (comme le citronellol, le géraniol et le linalol) afin d''assurer une traçabilité irréprochable et de simplifier vos démarches de validation toxicologique sur le marché européen en Catégorie 4 (Fine Fragrances).', 'Standard de Production : Filtration à froid et traitement doux pour préserver l''équilibre natif entre le géraniol et le citronellol au sein d''une matrice pure, selon les plus strictes directives de management de la qualité.
Authenticité Géographique : 100% Géranium d''Égypte issu de cultures locales contrôlées.
Contrôle Laboratoire : Les analyses sont réalisées selon les exigences du produit et du lot, auprès de laboratoires appropriés lorsque nécessaire.
Conditionnement de Transport Conforme aux Exigences Applicables : Expédié dans des conteneurs professionnels robustes en aluminium, scellés hermétiquement, garantissant une protection maximale contre l''oxydation thermique. Chaque unité est munie d''une étiquette technique standardisée de traçabilité (Sceau Bostan Naturals, SKU, Batch et Mentions légales).', 'Votre Traçabilité Commerciale sous Sceau de Confidentialité :
Pour préserver l''intégrité absolue de vos formules et garantir le secret commercial le plus strict concernant vos sources d''approvisionnement, chaque lot de Bostan Naturals is accompagné de son dossier réglementaire dédié, édité exclusivement sous notre nom de marque :
1. Télécharger la Fiche Technique de l''Absolue (TDS) liée au SKU BNABS005
2. Télécharger le Certificat d''Analyse (COA) Spécifique au Lot
3. Télécharger la Fiche de Données de Sécurité (FDS / MSDS) Conforme UE', 4);
INSERT INTO products (sku, category_key, name_fr, name_en, subtitle_fr, subtitle_en, inci, cas, origin, extraction_method_fr, extraction_method_en, short_description_fr, short_description_en, image, images, description_fr, specifications_fr, organoleptic_fr, regulatory_fr, quality_fr, confidentiality_fr, sort_order) VALUES ('BNABS006', 'absolues', 'Absolue de Basilic d''Égypte', 'Egyptian Basil Absolute', 'Le Bloc Aromatique Grand Vert – L''Essence Anisée Pure', 'The Great Green Aromatic Block – The Pure Aniseed Essence', 'Ocimum Basilicum Extract', '8015-73-4 / 84775-71-3', 'Égypte', 'Extraction secondaire à l''alcool éthylique à partir de la concrète de basilic primaire', 'Secondary Ethyl Alcohol Extraction from Primary Basil Concrete', 'Extraite directement des sommités fleuries et des feuilles fraîches d''Ocimum basilicum cultivé sous le climat idéal de l''Égypte, notre Absolue de Basilic de Bostan Naturals est un secret de formulation d''une puissance brute unique. Cet élixir raffiné déploie une signature olfactive d''une clarté fusante : une envolée fraîche, verte et herbacée coupante, qui s''ouvre rapidement sur un cœur intensément épicé et fortement anisé (estragole), rehaussé de notes de réglisse douces et d''un fond boisé-herbacé d''une grande persistance. Un ingrédient d''avant-garde indispensable pour ouvrir les notes de tête, apporter de la vibration, de la fraîcheur et une tension nerveuse noble aux compositions Fougères, Aromatiques et aux Colognes modernes de niche.', 'Extracted directly from the flowering tops and fresh leaves of Ocimum basilicum cultivated under Egypt''s ideal climate, our Bostan Naturals Basil Absolute is a formulation secret of unique raw power. This refined elixir unfolds an olfactory signature of fusing clarity: a fresh, green and sharply herbal opening, quickly moving into an intensely spicy and strongly aniseed heart (estragole), enhanced by sweet liquorice notes and a highly persistent woody-herbaceous base. An avant-garde ingredient indispensable for opening top notes, bringing vibration, freshness and a noble nervy tension to Fougère, Aromatic and modern niche Cologne compositions.', '/images/categories/absolues.jpg', '[]', 'ABSOLUE DE BASILIC D''ÉGYPTE
Le Bloc Aromatique Grand Vert – L''Essence Anisée Pure

Extraite directement des sommités fleuries et des feuilles fraîches d''Ocimum basilicum cultivé sous le climat idéal de l''Égypte, notre Absolue de Basilic de Bostan Naturals est un secret de formulation d''une puissance brute unique. Cet élixir raffiné déploie une signature olfactive d''une clarté fusante : une envolée fraîche, verte et herbacée coupante, qui s''ouvre rapidement sur un cœur intensément épicé et fortement anisé (estragole), rehaussé de notes de réglisse douces et d''un fond boisé-herbacé d''une grande persistance. Un ingrédient d''avant-garde indispensable pour ouvrir les notes de tête, apporter de la vibration, de la fraîcheur et une tension nerveuse noble aux compositions Fougères, Aromatiques et aux Colognes modernes de niche.', '["Nom INCI : Ocimum Basilicum Extract","Numéro CAS : 8015-73-4 / 84775-71-3","Code SKU : BNABS006","Source Botanique : Ocimum basilicum L. (Lamiaceae)","Origine : Égypte (100% Pure, Naturelle & Intègre)","Procédé : Extraction secondaire à l''alcool éthylique à partir de la concrète de basilic primaire"]', '["Aspect : Liquide mobile limpide.","Couleur : Vert foncé à brun verdâtre profond.","Odeur : Très puissante, fraîche, intensément herbacée, épicée, aux facettes d''anis et de réglisse très denses caractéristiques du basilic égyptien.","Indice de Réfraction @ 20°C : 1.4800 – 1.5100","Densité Relative @ 20°C : 0.9300 – 0.9650","Solubilité : Insoluble dans l''eau, parfaitement soluble dans l''alcool éthylique et les huiles."]', 'Sécurité Moléculaire & Conformité REACH
Chez Bostan Naturals, la rigueur technique est le bouclier de votre créativité. Notre Absolue de Basilic est conforme aux exigences et restrictions applicables de l''IFRA pour l''utilisation prévue de la matière en parfumerie (la dernière mise à jour en vigueur) et répond pleinement aux exigences de la réglementation européenne REACH. Pour chaque lot, nous suivons de près ses constituants actifs (notamment l''estragole et le linalol) par chromatographie afin d''assurer une sécurité dermatologique absolue et de faciliter l''évaluation réglementaire et la formulation de vos formules en Catégorie 4 (Fine Fragrances).', 'Standard de Production : Processus de déparaffinage à froid minutieusement régulé pour éliminer les cires lourdes tout en protégeant les molécules thermosensibles, selon les plus strictes directives de management de la qualité.
Traçabilité Botanique Royale : Basilic cultivé et récolté localement, certifié 100% égyptien.
Contrôle Laboratoire : Les analyses sont réalisées selon les exigences du produit et du lot, auprès de laboratoires appropriés lorsque nécessaire.
Conditionnement de Transport Conforme aux Exigences Applicables : Expédié en flacons d''aluminium professionnels épais hermétiques pour bloquer totalement l''air et préserver les précieuses facettes volatiles. Chaque unité est munie d''une étiquette technique standardisée de traçabilité (Sceau Bostan Naturals, SKU, Batch et Mentions légales).', 'Votre Traçabilité Commerciale sous Sceau de Confidentialité :
Pour préserver l''intégrité absolue de vos formules et garantir le secret commercial le plus strict concernant vos sources d''approvisionnement, chaque lot de Bostan Naturals est accompagné de son dossier réglementaire dédié, édité exclusivement sous notre nom de marque :
1. Télécharger la Fiche Technique de l''Absolue (TDS) liée au SKU BNABS006
2. Télécharger le Certificat d''Analyse (COA) Spécifique au Lot
3. Télécharger la Fiche de Données de Sécurité (FDS / MSDS) Conforme UE', 5);
INSERT INTO products (sku, category_key, name_fr, name_en, subtitle_fr, subtitle_en, inci, cas, origin, extraction_method_fr, extraction_method_en, short_description_fr, short_description_en, image, images, description_fr, specifications_fr, organoleptic_fr, regulatory_fr, quality_fr, confidentiality_fr, sort_order) VALUES ('BNABS007', 'absolues', 'Absolue de Petitgrain Bigarade d''Égypte', 'Egyptian Petitgrain Bigarade Absolute', 'Le Ciment Vert de l''Oranger – La Tension Ligneuse Amère Flanquée de Fleur', 'The Orange Tree''s Green Cement – The Bitter Woody Tension Flanked by Flower', 'Citrus Aurantium Amara Leaf/Twig Extract', '8014-17-3 / 72968-50-4', 'Égypte', 'Extraction secondaire à l''alcool éthylique à partir de la concrète de petitgrain primaire', 'Secondary Ethyl Alcohol Extraction from Primary Petitgrain Concrete', 'Obtenue par lavage alcoolique à partir de la concrète de bigaradier en Égypte, notre Absolue de Petitgrain Bigarade de Bostan Naturals est une exclusivité industrielle hautement technique. Cet élixir précieux concentre non seulement les notes vertes et boisées amères de la feuille et des jeunes rameaux, mais également les facettes miellées et florales sous-jacentes de la fleur d''oranger. Il se caractérise par une signature olfactive d''une intensité texturée : une attaque verte, vive et hépatique, qui évolue vers un cœur boisé-herbacé, adouci par des nuances de foin et une persistance cireuse magistrale. Un composant d''architecture essentiel pour insuffler du relief, de la tension, de la masculinité élégante et une tenue nerveuse aux structures Fougères, Boisées et aux Colognes modernes de niche.', 'Obtained by alcoholic washing from the bitter orange concrete in Egypt, our Bostan Naturals Petitgrain Bigarade Absolute is a highly technical industrial exclusive. This precious elixir concentrates not only the bitter green and woody notes of the leaf and young twigs, but also the underlying honeyed and floral facets of the orange blossom. It is characterised by an olfactory signature of textured intensity: a green, lively and hepatica-like attack, evolving into a woody-herbaceous heart, softened by hay nuances and a masterful waxy persistence. An essential architectural component for infusing relief, tension, elegant masculinity and a nervy hold into Fougère, Woody and modern niche Cologne structures.', '/images/categories/absolues.jpg', '[]', 'ABSOLUE DE PETITGRAIN BIGARADE D''ÉGYPTE
Le Ciment Vert de l''Oranger – La Tension Ligneuse Amère Flanquée de Fleur

Obtenue par lavage alcoolique à partir de la concrète de bigaradier en Égypte, notre Absolue de Petitgrain Bigarade de Bostan Naturals est une exclusivité industrielle hautement technique. Cet élixir précieux concentre non seulement les notes vertes et boisées amères de la feuille et des jeunes rameaux, mais également les facettes miellées et florales sous-jacentes de la fleur d''oranger. Il se caractérise par une signature olfactive d''une intensité texturée : une attaque verte, vive et hépatique, qui évolue vers un cœur boisé-herbacé, adouci par des nuances de foin et une persistance cireuse magistrale. Un composant d''architecture essentiel pour insuffler du relief, de la tension, de la masculinité élégante et une tenue nerveuse aux structures Fougères, Boisées et aux Colognes modernes de niche.', '["Nom INCI : Citrus Aurantium Amara Leaf/Twig Extract","Numéro CAS : 8014-17-3 / 72968-50-4","Code SKU : BNABS007","Source Botanique : Citrus aurantium var. amara L. (Rutaceae)","Origine : Égypte (100% Pure & Naturelle)","Procédé : Extraction secondaire à l''alcool éthylique à partir de la concrète de petitgrain primaire"]', '["Aspect : Liquide mobile limpide à légèrement visqueux.","Couleur : Vert olive très foncé à brun verdâtre.","Odeur : Puissante, verte-amère, boisée, avec des facettes florales cireuses et des notes de foin élastiques et persistantes.","Indice de Réfraction @ 20°C : 1.4850 – 1.5100","Densité Relative @ 20°C : 0.9400 – 0.9750","Solubilité : Insoluble dans l''eau, hautement compatible avec les huiles et les solvants de parfumerie."]', 'Protection Moléculaire et Traçabilité REACH
Chez Bostan Naturals, l''excellence technique protège votre marque. Notre Absolue de Petitgrain Bigarade est conforme aux exigences et restrictions applicables de l''IFRA pour l''utilisation prévue de la matière en parfumerie (la dernière mise à jour en vigueur) et répond scrupuleusement au protocole européen REACH. Nous suivons de près les concentrations naturelles d''allergènes volatils (comme l''acétate de linalyle, le linalol et le limonène) par chromatographie afin d''assurer une sécurité dermatologique absolue et de faciliter l''évaluation réglementaire et la formulation de vos parfums finis en Catégorie 4 (Fine Fragrances).', 'Standard de Production : Suivi strict des processus de filtration pour une standardisation parfaite du profil aromatique d''un lot à l''autre, selon les plus strictes directives de management de la qualité.
Origine Égyptienne 100% Traçable : Rameaux issus exclusivement des tailles saisonnières de nos cultures locales contrôlées.
Contrôle Laboratoire : Les analyses sont réalisées selon les exigences du produit et du lot, auprès de laboratoires appropriés lorsque nécessaire.
Conditionnement de Transport Conforme aux Exigences Applicables : Expédié dans des flacons d''aluminium professionnels professionnels étanches pour sécuriser l''expédition internationale et empêcher la dégradation des facettes aromatiques. Chaque unité est munie d''une étiquette technique standardisée de traçabilité (Sceau Bostan Naturals, SKU, Batch et Mentions légales).', 'Votre Traçabilité Commerciale sous Sceau de Confidentialité :
Pour préserver l''intégrité absolue de vos formules et garantir le secret commercial le plus strict concernant vos sources d''approvisionnement, chaque lot de Bostan Naturals est accompagné de son dossier réglementaire dédié, édité exclusivement sous notre nom de marque :
1. Télécharger la Fiche Technique de l''Absolue (TDS) liée au SKU BNABS007
2. Télécharger le Certificat d''Analyse (COA) Spécifique au Lot
3. Télécharger la Fiche de Données de Sécurité (FDS / MSDS) Conforme UE', 6);
INSERT INTO products (sku, category_key, name_fr, name_en, subtitle_fr, subtitle_en, inci, cas, origin, extraction_method_fr, extraction_method_en, short_description_fr, short_description_en, image, images, description_fr, specifications_fr, organoleptic_fr, regulatory_fr, quality_fr, confidentiality_fr, sort_order) VALUES ('BNABS008', 'absolues', 'Absolue de Jasmine Sambac d''Égypte', 'Egyptian Jasmine Sambac Absolute', 'La Cire Nocturne de l''Indole – L''Opulence Narcotique Fruitée Verte', 'The Nocturnal Wax of Indole – The Green Fruity Narcotic Opulence', 'Jasminum Sambac Flower Extract', '91770-14-8 / 1034798-23-6', 'Égypte', 'Extraction secondaire à l''alcool éthylique à partir de la concrète de jasmin sambac primaire', 'Secondary Ethyl Alcohol Extraction from Primary Jasmine Sambac Concrete', 'Issue du traitement des fleurs de Jasminum sambac récoltées à la tombée de la nuit dans nos domaines égyptiens, notre Absolue de Jasmin Sambac de Bostan Naturals est le paroxysme de la sensualité florale sauvage. Cet élixir extraordinaire concentre l''intégralité des composés indoliques lourds et des facettes fruitées exclusives de la fleur de فل. Il déploie une signature olfactive d''une force narcotique rare : une attaque vive, fruitée-verte (rappelant la peau de mangue et la fleur d''oranger), qui s''ouvre sur un cœur intensément floral blanc, lourd, miellé, et un fond animal-charnel d''une opulence absolue. Un ingrédient d''avant-garde hautement recherché par les créateurs de niche pour apporter de la vibration, du mystère, de la modernité et un contraste saisissant aux structures Florales et Orientales de prestige.', 'Issued from the treatment of Jasminum sambac flowers harvested at nightfall on our Egyptian estates, our Bostan Naturals Jasmine Sambac Absolute is the pinnacle of wild floral sensuality. This extraordinary elixir concentrates the entirety of heavy indolic compounds and exclusive fruity facets of the flower. It unfolds an olfactory signature of rare narcotic force: a lively, fruity-green attack (recalling mango skin and orange blossom), opening into an intensely white-floral, heavy, honeyed heart, and an animalic-carnal base of absolute opulence. A highly sought-after avant-garde ingredient for niche creators seeking to bring vibration, mystery, modernity and a striking contrast to prestigious Floral and Oriental structures.', '/images/categories/absolues.jpg', '[]', 'ABSOLUE DE JASMINE SAMBAC D''ÉGYPTE
La Cire Nocturne de l''Indole – L''Opulence Narcotique Fruitée Verte

Issue du traitement des fleurs de Jasminum sambac récoltées à la tombée de la nuit dans nos domaines égyptiens, notre Absolue de Jasmin Sambac de Bostan Naturals est le paroxysme de la sensualité florale sauvage. Cet élixir extraordinaire concentre l''intégralité des composés indoliques lourds et des facettes fruitées exclusives de la fleur de فل. Il déploie une signature olfactive d''une force narcotique rare : une attaque vive, fruitée-verte (rappelant la peau de mangue et la fleur d''oranger), qui s''ouvre sur un cœur intensément floral blanc, lourd, miellé, et un fond animal-charnel d''une opulence absolue. Un ingrédient d''avant-garde hautement recherché par les créateurs de niche pour apporter de la vibration, du mystère, de la modernité et un contraste saisissant aux structures Florales et Orientales de prestige.', '["Nom INCI : Jasminum Sambac Flower Extract","Numéro CAS : 91770-14-8 / 1034798-23-6","Code SKU : BNABS008","Source Botanique : Jasminum sambac (L.) Aiton (Oleaceae)","Origine : Égypte (100% Pure, Naturelle & Non altérée)","Procédé : Extraction secondaire à l''alcool éthylique à partir de la concrète de jasmin sambac primaire"]', '["Aspect : Liquide mobile fluide très limpide.","Couleur : Orange foncé à brun rouge profond.","Odeur : Intensément florale blanche, lourde, hautement indolique, plus fruitée-verte, miellée et animale que le Grandiflorum.","Indice de Réfraction @ 20°C : 1.4900 – 1.5190","Densité Relative @ 20°C : 0.9500 – 0.9890","Solubilité : Insoluble dans l''eau, totalement soluble dans l''éthanol et les solvants organiques de parfumerie."]', 'Sécurité Moléculaire & Préservation des Anthranilates
La Absolue de Jasmin Sambac Bostan Naturals garantit la stabilisation des esters aromatiques complexes au cœur de sa matrice. Des analyses des solvants résiduels sont réalisées lorsque cela est applicable au produit et à son procédé d''extraction, et elle répond scrupuleusement aux critères du règlement REACH européen et aux dernières restrictions de l''IFRA (la dernière mise à jour en vigueur) pour les matières de haute cosmétique et la formulation en Catégorie 4 (Fine Fragrances).', 'Standard de Production : Processus d''extraction physique standardisé sous vide et glaçage contrôlé pour éliminer les cires végétales lourdes, selon les plus strictes directives de management de la qualité.
Certification d''Origine Géographique : Fleurs de فل égyptien à 100% issues de nos filières contrôlées.
Contrôle Laboratoire : Les analyses sont réalisées selon les exigences du produit et du lot, auprès de laboratoires appropriés lorsque nécessaire.
Conditionnement de Transport Conforme aux Exigences Applicables : Expédié dans des conteneurs professionnels robustes en aluminium, scellés hermétiquement, garantissant une protection maximale contre l''oxydation thermique. Chaque unité est munie d''une étiquette technique standardisée de traçabilité (Sceau Bostan Naturals, SKU, Batch et Mentions légales).', 'Votre Traçabilité Commerciale sous Sceau de Confidentialité :
Pour préserver l''intégrité absolue de vos formules et garantir le secret commercial le plus strict concernant vos sources d''approvisionnement, chaque lot de Bostan Naturals est accompagné de son dossier réglementaire dédié, édité exclusivement sous notre nom de marque :
1. Télécharger la Fiche Technique de l''Absolue (TDS) liée au SKU BNABS008
2. Télécharger le Certificat d''Analyse (COA) Spécifique au Lot
3. Télécharger la Fiche de Données de Sécurité (FDS / MSDS) Conforme UE', 7);
INSERT INTO products (sku, category_key, name_fr, name_en, subtitle_fr, subtitle_en, inci, cas, origin, extraction_method_fr, extraction_method_en, short_description_fr, short_description_en, image, images, description_fr, specifications_fr, organoleptic_fr, regulatory_fr, quality_fr, confidentiality_fr, sort_order) VALUES ('BNABS009', 'absolues', 'Absolue de Feuilles de Violette d''Égypte', 'Egyptian Violet Leaf Absolute', 'Le Bloc Vert Émeraude – La Force Cuirée Métallique Tranchante', 'The Emerald Green Block – The Sharp Metallic Leathery Force', 'Viola Odorata Leaf Extract', '8024-08-6 / 90131-42-3', 'Égypte', 'Extraction secondaire à l''alcool éthylique fort à partir de la concrète de violette fraîche', 'Secondary Strong Ethyl Alcohol Extraction from Fresh Violet Concrete', 'L''Égypte dominant historiquement cette culture, notre Absolue de Feuilles de Violette de Bostan Naturals est un joyau architectural irremplaçable pour la parfumerie fine masculine et mixte. Cet élixir raffiné déploie une signature olfactive d''une verdeur tranchante phénoménale. Il s''ouvre sur des notes de tête intenses, métalliques et herbeuses coupantes (évoquant le concombre froissé et la sève de printemps), avant de révéler un cœur texturé qui évolue magistralement vers un fond massif de cuir chamoisé, boisé et terreux d''une persistance souveraine. Un composant d''architecture indispensable pour apporter de la tension, du relief vertical, de l''envolée verte et un chic intemporel aux structures Fougères, Cuirs, Boisées et aux créations masculines de luxe.', 'Dominating this culture historically, our Bostan Naturals Violet Leaf Absolute is an irreplaceable architectural gem for fine masculine and unisex perfumery. This refined elixir unfolds an olfactory signature of phenomenal sharp greenness. It opens with intense, metallic, sharply herbaceous top notes (evoking crumpled cucumber and spring sap), before revealing a textured heart that masterfully evolves into a massive base of chamois leather, woody and earthy notes of sovereign persistence. An indispensable architectural component for bringing tension, vertical lift, green burst and timeless chic to Fougère, Leather, Woody and luxury masculine creations.', '/images/categories/absolues.jpg', '[]', 'ABSOLUE DE FEUILLES DE VIOLETTE D''ÉGYPTE
Le Bloc Vert Émeraude – La Force Cuirée Métallique Tranchante

L''Égypte dominant historiquement cette culture, notre Absolue de Feuilles de Violette de Bostan Naturals est un joyau architectural irremplaçable pour la parfumerie fine masculine et mixte. Cet élixir raffiné déploie une signature olfactive d''une verdeur tranchante phénoménale. Il s''ouvre sur des notes de tête intenses, métalliques et herbeuses coupantes (évoquant le concombre froissé et la sève de printemps), avant de révéler un cœur texturé qui évolue magistralement vers un fond massif de cuir chamoisé, boisé et terreux d''une persistance souveraine. Un composant d''architecture indispensable pour apporter de la tension, du relief vertical, de l''envolée verte et un chic intemporel aux structures Fougères, Cuirs, Boisées et aux créations masculines de luxe.', '["Nom INCI : Viola Odorata Leaf Extract","Numéro CAS : 8024-08-6 / 90131-42-3","Code SKU : BNABS009","Source Botanique : Viola odorata L. (Idem Violae / Violaceae)","Origine : Égypte (100% Pure, Naturelle & Pure Souche)","Procédé : Extraction secondaire à l''alcool éthylique fort à partir de la concrète de violette fraîche"]', '["Aspect : Liquide visqueux mobile limpide (viscosité moyenne).","Couleur : Vert émeraude très foncé à brun verdâtre profond opaque.","Odeur : Extrêmement puissante, herbeuse coupante, métallique, avec un fond cuiré, terreux et boisé massif caractéristique de la feuille de violette égyptienne.","Indice de Réfraction @ 20°C : 1.4750 – 1.5000","Densité Relative @ 20°C : 0.9200 – 0.9600","Solubilité : Insoluble dans l''eau, miscible avec les solvants organiques de parfumerie, parfaitement soluble dans l''éthanol fort."]', 'Stabilité des Aldéhydes Verts & Conformité REACH
La Absolue de Feuilles de Violette Bostan Naturals stabilise les précieux aldéhydes et acides insaturés naturels (nonadiénal) contre l''oxydation grâce à son procédé exclusif de filtration. Produit 100% naturel et tracé par lot dans nos laboratoires, il répond pleinement aux exigences de la réglementation européenne REACH et s''aligne scrupuleusement sur les limites de l''IFRA (la dernière mise à jour en vigueur) pour la Catégorie 4 (Fine Fragrances).', 'Standard de Production : Déparaffinage et filtration sous atmosphère inerte pour garantir un fluide dense et standardisé, selon les plus strictes directives de management de la qualité.
Approvisionnement Durable Garanti : Feuilles issues de récoltes écoresponsables sous contrôle exclusif dans nos terroirs dédiés.
Contrôle Laboratoire : Les analyses sont réalisées selon les exigences du produit et du lot, auprès de laboratoires appropriés lorsque nécessaire.
Conditionnement de Transport Conforme aux Exigences Applicables : Conditionné sous flacons professionnels en aluminium étanches pour bloquer totalement l''air et la lumière, protégeant ainsi les précieux éléments verts de l''oxydation thermique. Chaque unité est munie d''une étiquette technique standardisée de traçabilité (Sceau Bostan Naturals, SKU, Batch et Mentions légales).', 'La Protection Intégrale de Vos Secrets d''Approvisionnement :
Pour préserver le secret le plus strict entourant vos approvisionnements en matières premières stratégiques, Bostan Naturals publie l''intégralité des documents techniques sous son propre sceau commercial :
1. Télécharger la Fiche Technique de l''Absolue (TDS) liée au SKU BNABS009
2. Télécharger le Certificat d''Analyse (COA) Spécifique au Lot
3. Télécharger la Fiche de Données de Sécurité (FDS / MSDS) Conforme UE', 8);
INSERT INTO products (sku, category_key, name_fr, name_en, subtitle_fr, subtitle_en, inci, cas, origin, extraction_method_fr, extraction_method_en, short_description_fr, short_description_en, image, images, description_fr, specifications_fr, organoleptic_fr, regulatory_fr, quality_fr, confidentiality_fr, sort_order) VALUES ('BNCON001', 'concretes', 'Concrète de Cassie d''Égypte', 'Egyptian Cassie Concrete', 'Le Sphinx Doré – L''Énigme Florale Cuirée Intrépide', 'The Golden Sphinx – The Bold Leathery Floral Enigma', 'Acacia Farnesiana Flower Extract', '8023-82-3 / 89957-43-7', 'Égypte', 'Première extraction aux solvants volatils sélectifs sur fleurs fraîches d''hiver', 'Primary Extraction with Selective Volatile Solvents on Fresh Winter Flowers', 'Obtenue par extraction primaire par solvants volatils à partir des fleurs d''Acacia farnesiana mûries sous le soleil d''hiver en Égypte, notre Concrète de Cassie de Bostan Naturals est une matière première d''exception. Cette pâte solide cireuse concentre non seulement les huiles aromatiques absolues de la fleur, mais emprisonne également les cires cuticulaires lourdes et les pigments lipidiques de la plante. Elle déploie un parfum d''une densité phénoménale, floral et chaud, aux facettes poudrées et miellées puissantes, soutenues par un fond boisé, herbacé et cuiré d''une ténacité souveraine. C''est la structure brute cireuse indispensable que notre usine utilise pour filtrer le précieux absolu de cassie destiné à la haute parfumerie de niche.', 'Obtained by primary extraction with volatile solvents from Acacia farnesiana flowers ripened under Egypt''s winter sun, our Bostan Naturals Cassie Concrete is an exceptional raw material. This solid waxy paste not only concentrates the absolute aromatic oils of the flower, but also traps the heavy cuticular waxes and lipidic pigments of the plant. It unfolds a fragrance of phenomenal density, floral and warm, with powerful powdery and honeyed facets, supported by a woody, herbaceous and leathery base of sovereign tenacity. It is the indispensable raw waxy structure that our factory uses to filter the precious cassie absolute destined for high-end niche perfumery.', '/images/categories/concretes.jpg', '[]', 'CONCRÈTE DE CASSIE D''ÉGYPTE
Le Sphinx Doré – L''Énigme Florale Cuirée Intrépide

Obtenue par extraction primaire par solvants volatils à partir des fleurs d''Acacia farnesiana mûries sous le soleil d''hiver en Égypte, notre Concrète de Cassie de Bostan Naturals est une matière première d''exception. Cette pâte solide cireuse concentre non seulement les huiles aromatiques absolues de la fleur, mais emprisonne également les cires cuticulaires lourdes et les pigments lipidiques de la plante. Elle déploie un parfum d''une densité phénoménale, floral et chaud, aux facettes poudrées et miellées puissantes, soutenues par un fond boisé, herbacé et cuiré d''une ténacité souveraine. C''est la structure brute cireuse indispensable que notre usine utilise pour filtrer le précieux absolu de cassie destiné à la haute parfumerie de niche.', '["Nom INCI : Acacia Farnesiana Flower Extract","Numéro CAS : 8023-82-3 / 89957-43-7","Code SKU : BNCON001","Source Botanique : Acacia farnesiana (L.) Willd. (Fabaceae)","Origine : Égypte (100% Pure & Naturelle)","Procédé : Première extraction aux solvants volatils sélectifs sur fleurs fraîches d''hiver"]', '["Aspect : Masse solide cireuse compacte à semi-solide.","Couleur : Jaune ambré foncé à brun verdâtre profond.","Odeur : Florale dense, poudrée, intensément miellée, avec des facettes boisées et un sillage cuiré-animal massif et persistant.","Point de Fusion (Melting Point) : 45°C – 52°C","Solubilité : Insoluble dans l''eau, hautement compatible avec les huiles et les solvants de parfumerie."]', 'Protection Moléculaire et Traçabilité REACH
La Concrète de Cassie Bostan Naturals protège naturellement ses esters volatiles contre l''hydrolyse grâce à sa matrice cireuse anhydre. Ce produit technique de premier stade est entièrement validé conforme au règlement européen REACH, assurant une sécurité absolue pour le développement de cosmétiques solides, d''onguents et de parfums d''auteur.', 'Standard de Production : Extraction industrielle encadrée éliminant tout risque de surchauffe ou de dénaturation des composés, selon les plus strictes directives de management de la qualité.
Origine Égyptienne 100% Traçable : Fleurs issues de récoltes locales hivernales sous contrôle exclusif.
Contrôle Laboratoire : Les analyses sont réalisées selon les exigences du produit et du lot, auprès de laboratoires appropriés lorsque nécessaire.
Conditionnement de Transport Conforme aux Exigences Applicables : Expédié dans des conteneurs professionnels robustes, scellés hermétiquement, garantissant une protection maximale contre l''oxydation et les variations thermiques. Chaque unité est munie d''une étiquette technique standardisée de traçabilité (Sceau Bostan Naturals, SKU, Batch et Mentions légales).', 'Votre Traçabilité Commerciale sous Sceau de Confidentialité :
Pour préserver l''intégrité absolue de vos formules et garantir le secret commercial le plus strict concernant vos sources d''approvisionnement, chaque lot de Bostan Naturals est accompagné de son dossier réglementaire dédié, édité exclusivement sous notre nom de marque :
1. Télécharger la Fiche Technique de la Concrète (TDS) liée au SKU BNCON001
2. Télécharger le Certificat d''Analyse des Cires Mères Spécifique au Lot
3. Télécharger la Fiche de Données de Sécurité (FDS / MSDS) Conforme UE', 9);
INSERT INTO products (sku, category_key, name_fr, name_en, subtitle_fr, subtitle_en, inci, cas, origin, extraction_method_fr, extraction_method_en, short_description_fr, short_description_en, image, images, description_fr, specifications_fr, organoleptic_fr, regulatory_fr, quality_fr, confidentiality_fr, sort_order) VALUES ('BNCON002', 'concretes', 'Concrète de Jasmine Grandiflorum d''Égypte', 'Egyptian Jasmine Grandiflorum Concrete', 'La Reine du Nil – L''Opulence Florale Blanche Indolique Mère', 'The Queen of the Nile – The Mother White Floral Indolic Opulence', 'Jasminum Grandiflorum Flower Extract', '8022-43-1 / 84776-64-7', 'Égypte', 'Première extraction aux solvants volatils d''hydrocarbures légers sur fleurs fraîches cueillies à l''aube', 'Primary Extraction with Light Hydrocarbon Volatile Solvents on Fresh Flowers Harvested at Dawn', 'Issue de la première extraction par solvants des fleurs de Jasminum grandiflorum cueillies à la main à l''aube dans le delta du Nil, notre Concrète de Jasmin Grandiflorum de Bostan Naturals incarne la pureté primitive de la fleur fraîche. Cette pâte solide d''une richesse exceptionnelle emprisonne l''intégralité des cires végétales naturelles, des esters volatils et des composés indoliques lourds de la fleur. Elle déploie une signature olfactive monumentale : une envolée florale blanche intense, chaleureuse, fruitée-miellée, sur un fond balsamique-animal d''une ténacité magnétique incomparable. C''est la pâte mère exclusive qui sert de souche à notre laboratoire pour filtrer le prestigieux absolu de jasmin.', 'Issued from the primary solvent extraction of Jasminum grandiflorum flowers hand-picked at dawn in the Nile Delta, our Bostan Naturals Jasmine Grandiflorum Concrete embodies the primitive purity of the fresh flower. This solid paste of exceptional richness traps the entirety of the natural vegetable waxes, volatile esters and heavy indolic compounds of the flower. It unfolds a monumental olfactory signature: an intense, warm, fruity-honeyed white floral burst, over a balsamic-animalic base of incomparable magnetic tenacity. It is the exclusive mother paste that serves as the source for our laboratory to filter the prestigious jasmine absolute.', '/images/categories/concretes.jpg', '[]', 'CONCRÈTE DE JASMINE GRANDIFLORUM D''ÉGYPTE
La Reine du Nil – L''Opulence Florale Blanche Indolique Mère

Issue de la première extraction par solvants des fleurs de Jasminum grandiflorum cueillies à la main à l''aube dans le delta du Nil, notre Concrète de Jasmin Grandiflorum de Bostan Naturals incarne la pureté primitive de la fleur fraîche. Cette pâte solide d''une richesse exceptionnelle emprisonne l''intégralité des cires végétales naturelles, des esters volatils et des composés indoliques lourds de la fleur. Elle déploie une signature olfactive monumentale : une envolée florale blanche intense, chaleureuse, fruitée-miellée, sur un fond balsamique-animal d''une ténacité magnétique incomparable. C''est la pâte mère exclusive qui sert de souche à notre laboratoire pour filtrer le prestigieux absolu de jasmin.', '["Nom INCI : Jasminum Grandiflorum Flower Extract","Numéro CAS : 8022-43-1 / 84776-64-7","Code SKU : BNCON002","Source Botanique : Jasminum grandiflorum L. (Oleaceae)","Origine : Égypte (100% Pure & Naturelle)","Procédé : Première extraction aux solvants volatils d''hydrocarbures légers sur fleurs fraîches cueillies à l''aube"]', '["Aspect : Masse solide cireuse compacte à semi-solide.","Couleur : Brun orangé foncé à rouge ambré profond.","Odeur : Intensément florale blanche, lourde, fruitée, voluptueuse, avec des sous-tons animaux et indoliques nobles très puissants.","Point de Fusion (Melting Point) : 46°C – 52°C","Solubilité : Insoluble dans l''eau, soluble dans les huiles végétales et solvants organiques gras."]', 'Sécurité Moléculaire & Préservation des Esters
La Concrète de Jasmin Grandiflorum Bostan Naturals stabilise les précieux acétates de benzyle natifs au cœur de ses cires végétales. Certifiée 100% pure et sans altération, elle répond pleinement aux critères du règlement REACH européen pour les matières de haute cosmétique.', 'Standard de Production : Processus d''extraction physique standardisé sous vide et température contrôlée, selon les plus strictes directives de management de la qualité.
Certification d''Origine Géographique : 100% Jasmin d''Égypte issu de récoltes écoresponsables tracées.
Contrôle Laboratoire : Les analyses sont réalisées selon les exigences du produit et du lot, auprès de laboratoires appropriés lorsque nécessaire.
Conditionnement de Transport Conforme aux Exigences Applicables : Expédié dans des conteneurs professionnels robustes, scellés hermétiquement, garantissant une protection maximale contre l''oxydation thermique. Chaque unité est munie d''une étiquette technique standardisée de traçabilité (Sceau Bostan Naturals, SKU, Batch et Mentions légales).', 'Votre Traçabilité Commerciale sous Sceau de Confidentialité :
Pour préserver l''intégrité absolue de vos formules et garantir le secret commercial le plus strict concernant vos sources d''approvisionnement, chaque lot de Bostan Naturals est accompagné de son dossier réglementaire dédié, édité exclusivement sous notre nom de marque :
1. Télécharger la Fiche Technique de la Concrète (TDS) liée au SKU BNCON002
2. Télécharger le Certificat de Conformité des Cires Mères Spécifique au Lot
3. Télécharger la Fiche de Données de Sécurité (FDS / MSDS) Conforme UE', 10);
INSERT INTO products (sku, category_key, name_fr, name_en, subtitle_fr, subtitle_en, inci, cas, origin, extraction_method_fr, extraction_method_en, short_description_fr, short_description_en, image, images, description_fr, specifications_fr, organoleptic_fr, regulatory_fr, quality_fr, confidentiality_fr, sort_order) VALUES ('BNCON003', 'concretes', 'Concrète de Fleur d''Oranger d''Égypte', 'Egyptian Orange Blossom Concrete', 'Le Crépuscule d''Or – L''Opulence Florale Animale Sacrée Mère', 'The Golden Dusk – The Sacred Mother Animalic Floral Opulence', 'Citrus Aurantium Amara Flower Extract', '8030-28-2 / 72968-50-4', 'Égypte', 'Première extraction aux solvants volatils d''hydrocarbures sur fleurs fraîches de printemps', 'Primary Extraction with Hydrocarbon Volatile Solvents on Fresh Spring Flowers', 'Extraite des pétales frais du bigaradier (Citrus aurantium var. amara) récoltés au printemps en Égypte, notre Concrète de Fleur d''Oranger de Bostan Naturals est un bloc de cire florale d''une richesse exceptionnelle. Ce ciment végétal emprisonne les cires cuticulaires lourdes, les pigments naturels de la fleur et ses notes les plus charnelles. Il déploie un parfum d''une puissance rare, floral-orangé intense, sucré et miellé, plongé dans un cœur fortement cireux, vert-amande et indolique, sur un fond animal et balsamique persistant. C''est la souche brute non modifiée qui sert à filtrer notre précieux absolu de fleur d''oranger de luxe.', 'Extracted from the fresh petals of the bitter orange tree (Citrus aurantium var. amara) harvested in spring in Egypt, our Bostan Naturals Orange Blossom Concrete is a block of floral wax of exceptional richness. This vegetable cement traps the heavy cuticular waxes, the natural pigments of the flower and its most carnal notes. It unfolds a fragrance of rare power, intense floral-orange, sweet and honeyed, soaked in a strongly waxy, green-almond and indolic heart, over a persistent animalic and balsamic base. It is the unmodified raw stock used to filter our precious luxury orange blossom absolute.', '/images/categories/concretes.jpg', '[]', 'CONCRÈTE DE FLEUR D''ORANGER D''ÉGYPTE
Le Crépuscule d''Or – L''Opulence Florale Animale Sacrée Mère

Extraite des pétales frais du bigaradier (Citrus aurantium var. amara) récoltés au printemps en Égypte, notre Concrète de Fleur d''Oranger de Bostan Naturals est un bloc de cire florale d''une richesse exceptionnelle. Ce ciment végétal emprisonne les cires cuticulaires lourdes, les pigments naturels de la fleur et ses notes les plus charnelles. Il déploie un parfum d''une puissance rare, floral-orangé intense, sucré et miellé, plongé dans un cœur fortement cireux, vert-amande et indolique, sur un fond animal et balsamique persistant. C''est la souche brute non modifiée qui sert à filtrer notre précieux absolu de fleur d''oranger de luxe.', '["Nom INCI : Citrus Aurantium Amara Flower Extract","Numéro CAS : 8030-28-2 / 72968-50-4","Code SKU : BNCON003","Source Botanique : Citrus aurantium var. amara L. (Rutaceae)","Origine : Égypte (100% Pure & Naturelle)","Procédé : Première extraction aux solvants volatils d''hydrocarbures sur fleurs fraîches de printemps"]', '["Aspect : Masse solide cireuse compacte (Waxy solid mass).","Couleur : Brun ambré foncé à rouge orangé profond.","Odeur : Puissante, florale-orangée intense, lourde, miellée, aux facettes animales, indoliques et cireuses très prononcées.","Point de Fusion (Melting Point) : 47°C – 54°C","Solubilité : Insoluble dans l''eau, hautement compatible avec les huiles et les corps gras de parfumerie."]', 'Stabilité Moléculaire & Conformité REACH
La Concrète de Fleur d''Oranger Bostan Naturals stabilise les précieux anthranilates et esters aromatiques au cœur de ses cires végétales contre l''oxydation. Produit 100% naturel et tracé, il répond scrupuleusement aux exigences de la réglementation européenne REACH.', 'Standard de Production : Suivi rigoureux de l''évaporation du solvant pour garantir un bloc de concrète dense et standardisé, selon les plus strictes directives de management de la qualité.
Qualité Botanique Certifiée : Fleurs récoltées exclusivement auprès de nos filières agricoles locales contrôlées.
Contrôle Laboratoire : Les analyses sont réalisées selon les exigences du produit et du lot, auprès de laboratoires appropriés lorsque nécessaire.
Conditionnement de Transport Conforme aux Exigences Applicables : Conditionné sous emballage professionnel hermétique pour bloquer totalement l''air et la lumière, protégeant ainsi le produit. Chaque unité est munie d''une étiquette technique standardisée de traçabilité (Sceau Bostan Naturals, SKU, Batch et Mentions légales).', 'La Protection Intégrale de Vos Secrets d''Approvisionnement :
Pour préserver le secret le plus strict entourant vos approvisionnements en matières premières stratégiques, Bostan Naturals publie l''intégralité des documents techniques sous son propre sceau commercial :
1. Télécharger la Fiche Technique de la Concrète (TDS) liée au SKU BNCON003
2. Télécharger le Certificat de pureté des Cires Spécifique au Lot
3. Télécharger la Fiche de Données de Sécurité (FDS / MSDS) Conforme UE', 11);
INSERT INTO products (sku, category_key, name_fr, name_en, subtitle_fr, subtitle_en, inci, cas, origin, extraction_method_fr, extraction_method_en, short_description_fr, short_description_en, image, images, description_fr, specifications_fr, organoleptic_fr, regulatory_fr, quality_fr, confidentiality_fr, sort_order) VALUES ('BNCON004', 'concretes', 'Concrète de Caroube d''Égypte', 'Egyptian Carob Concrete', 'Le Nectar d''Alexandrie – La Matrice Gourmande et Ambrée Brute', 'The Nectar of Alexandria – The Raw Gourmand and Amber Matrix', 'Ceratonia Siliqua Fruit Extract', '84961-45-5 / 9000-40-2', 'Égypte', 'Première extraction aux solvants volatils organiques sur gousses sèches sélectionnées', 'Primary Extraction with Organic Volatile Solvents on Selected Dry Pods', 'Obtenue par extraction primaire aux solvants volatils à partir des gousses riches en sucres complexes du caroubier mûries sous la chaleur sèche égyptienne, notre Concrète de Caroube de Bostan Naturals est une matière première exclusive. Cette masse compacte emprisonne les cires lipidiques lourdes et les résines naturelles de la gousse. Elle déploie une signature olfactive profondément addictive et facettée, aux notes de caramel brûlé, de chicorée torréfiée, de cacao ambré et de tabac de luxe blond. C''est le bloc de cire d''origine à partir duquel notre laboratoire extrait l''absolu de caroube, garantissant une authenticité souveraine pour la parfumerie fine.', 'Obtained by primary extraction with volatile solvents from the sugar-rich pods of the carob tree ripened under Egypt''s dry heat, our Bostan Naturals Carob Concrete is an exclusive raw material. This compact mass traps the heavy lipidic waxes and the natural resins of the pod. It unfolds a deeply addictive and faceted olfactory signature, with notes of burnt caramel, roasted chicory, amber cocoa and luxury blond tobacco. It is the original block of wax from which our laboratory extracts the carob absolute, guaranteeing sovereign authenticity for fine perfumery.', '/images/categories/concretes.jpg', '[]', 'CONCRÈTE DE CAROUBE D''ÉGYPTE
Le Nectar d''Alexandrie – La Matrice Gourmande et Ambrée Brute

Obtenue par extraction primaire aux solvants volatils à partir des gousses riches en sucres complexes du caroubier mûries sous la chaleur sèche égyptienne, notre Concrète de Caroube de Bostan Naturals est une matière première exclusive. Cette masse compacte emprisonne les cires lipidiques lourdes et les résines naturelles de la gousse. Elle déploie une signature olfactive profondément addictive et facettée, aux notes de caramel brûlé, de chicorée torréfiée, de cacao ambré et de tabac de luxe blond. C''est le bloc de cire d''origine à partir duquel notre laboratoire extrait l''absolu de caroube, garantissant une authenticité souveraine pour la parfumerie fine.', '["Nom INCI : Ceratonia Siliqua Fruit Extract","Numéro CAS : 84961-45-5 / 9000-40-2","Code SKU : BNCON004","Source Botanique : Ceratonia siliqua L. (Fabaceae)","Origine : Égypte (100% Pure & Naturelle)","Procédé : Première extraction aux solvants volatils organiques sur gousses sèches sélectionnées"]', '["Aspect : Masse solide cireuse très compacte, dure à semi-solide.","Couleur : Brun chocolat très foncé à noir ambré opaque.","Odeur : Puissamment balsamique, chaude, sucrée-amère, de caramel, de chicorée et de foin sec persistant.","Point de Fusion (Melting Point) : 49°C – 56°C","Solubilité : Insoluble dans l''eau, miscible avec les solvants organiques gras et cires végétales."]', 'Sécurité Moléculaire & Conformité REACH
La Concrète de Caroube Bostan Naturals garantit l''absence totale d''additifs ou de cires de remplissage synthétiques. Produit 100% tracé et conforme, il répond scrupuleusement aux exigences de la réglementation européenne REACH pour les formulations de haute cosmétique.', 'Standard de Production : Contrôle strict de l''extraction industrielle éliminant tout risque de surchauffe ou de dénaturation des composés, selon les plus strictes directives de management de la qualité.
Authenticité Géographique : Caroubes issues exclusivement de cultures égyptiennes locales contrôlées.
Contrôle Laboratoire : Les analyses sont réalisées selon les exigences du produit et du lot, auprès de laboratoires appropriés lorsque nécessaire.
Conditionnement de Transport Conforme aux Exigences Applicables : Expédié dans des conteneurs professionnels robustes, scellés hermétiquement, garantissant une protection maximale. Chaque unité est munie d''une étiquette technique standardisée de traçabilité (Sceau Bostan Naturals, SKU, Batch et Mentions légales).', 'Votre Traçabilité Commerciale sous Sceau de Confidentialité :
Pour préserver l''intégrité absolue de vos formules et garantir le secret commercial le plus strict concernant vos sources d''approvisionnement, chaque lot de Bostan Naturals est accompagné de son dossier réglementaire dédié, édité exclusivement sous notre nom de marque :
1. Télécharger la Fiche Technique de la Concrète (TDS) liée au SKU BNCON004
2. Télécharger le Certificat d''Analyse des Cires Spécifique au Lot
3. Télécharger la Fiche de Données de Sécurité (FDS / MSDS) Conforme UE', 12);
INSERT INTO products (sku, category_key, name_fr, name_en, subtitle_fr, subtitle_en, inci, cas, origin, extraction_method_fr, extraction_method_en, short_description_fr, short_description_en, image, images, description_fr, specifications_fr, organoleptic_fr, regulatory_fr, quality_fr, confidentiality_fr, sort_order) VALUES ('BNCON005', 'concretes', 'Concrète de Géranium d''Égypte', 'Egyptian Geranium Concrete', 'Le Sceptre Vert – La Vibration Rosée Herbacée Mère', 'The Green Scepter – The Rosy Herbaceous Mother Vibration', 'Pelargonium Graveolens Extract', '90082-51-2 / 8000-46-2', 'Égypte', 'Première extraction aux solvants volatils organiques sélectifs sur parties aériennes fraîches', 'Primary Extraction with Selective Organic Volatile Solvents on Fresh Aerial Parts', 'Extraite par solvants volatils à partir des feuilles et tiges fraîches de Pelargonium graveolens cultivées sur nos domaines en Égypte, notre Concrète de Géranium de Bostan Naturals est un ciment végétal d''une puissance brute unique. Cette masse solide cireuse emprisonne l''intégralité des cires cuticulaires lourdes, des chlorophylles et des précieux esters floraux de la plante. Elle déploie un parfum d''une richesse inouïe, fortement herbacé, vert et menthé, qui révèle un cœur intensément rosé rehaussé de facettes terreuses d''une élégance rare. C''est le bloc de cire d''origine indispensable utilisé par notre usine pour filtrer le précieux absolu de géranium destiné à la parfumerie fine.', 'Extracted with volatile solvents from the fresh leaves and stems of Pelargonium graveolens cultivated on our estates in Egypt, our Bostan Naturals Geranium Concrete is a vegetable cement of unique raw power. This solid waxy mass traps the entirety of the heavy cuticular waxes, the chlorophylls and the precious floral esters of the plant. It unfolds a fragrance of unheard-of richness, strongly herbaceous, green and minty, revealing an intensely rosy heart enhanced by earthy facets of rare elegance. It is the indispensable original block of wax used by our factory to filter the precious geranium absolute destined for fine perfumery.', '/images/categories/concretes.jpg', '[]', 'CONCRÈTE DE GÉRANIUM D''ÉGYPTE
Le Sceptre Vert – La Vibration Rosée Herbacée Mère

Extraite par solvants volatils à partir des feuilles et tiges fraîches de Pelargonium graveolens cultivées sur nos domaines en Égypte, notre Concrète de Géranium de Bostan Naturals est un ciment végétal d''une puissance brute unique. Cette masse solide cireuse emprisonne l''intégralité des cires cuticulaires lourdes, des chlorophylles et des précieux esters floraux de la plante. Elle déploie un parfum d''une richesse inouïe, fortement herbacé, vert et menthé, qui révèle un cœur intensément rosé rehaussé de facettes terreuses d''une élégance rare. C''est le bloc de cire d''origine indispensable utilisé par notre usine pour filtrer le précieux absolu de géranium destiné à la parfumerie fine.', '["Nom INCI : Pelargonium Graveolens Extract","Numéro CAS : 90082-51-2 / 8000-46-2","Code SKU : BNCON005","Source Botanique : Pelargonium graveolens L''Hér. (Geraniaceae)","Origine : Égypte (100% Pure & Naturelle)","Procédé : Première extraction aux solvants volatils organiques sélectifs sur parties aériennes fraîches"]', '["Aspect : Masse solide cireuse compacte à semi-solide.","Couleur : Vert olive foncé à vert émeraude profond.","Odeur : Puissante, florale-rosée intense, fortement herbacée, cireuse avec des facettes terreuses et menthées prononcées caractéristiques du géranium égyptien.","Point de Fusion (Melting Point) : 44°C – 51°C","Solubilité : Insoluble dans l''eau, parfaitement soluble dans les solvants organiques et solvants gras de parfumerie."]', 'Stabilité Moléculaire & Conformité REACH
La Concrète de Géranium Bostan Naturals stabilise les précieux alcools terpéniques (citronellol, géraniol) contre l''oxydation de l''air grâce à sa gangue cireuse anhydre. Produit 100% naturel et tracé, il répond pleinement aux exigences de la réglementation européenne REACH.', 'Standard de Production : Suivi strict des processus de traitement pour une standardisation parfaite du profil aromatique d''un lot à l''autre, selon les plus strictes directives de management de la qualité.
Authenticité Géographique Garantie : 100% Géranium d''Égypte issu de cultures locales contrôlées.
Contrôle Laboratoire : Les analyses sont réalisées selon les exigences du produit et du lot, auprès de laboratoires appropriés lorsque nécessaire.
Conditionnement de Transport Conforme aux Exigences Applicables : Expédié dans des conteneurs professionnels robustes, scellés hermétiquement, garantissant une protection maximale. Chaque unité est munie d''une étiquette technique standardisée de traçabilité (Sceau Bostan Naturals, SKU, Batch et Mentions légales).', 'La Garantie du Secret Commercial de Vos Formules :
Afin de protéger vos intérêts commerciaux et de masquer l''origine de vos matières premières stratégiques, Bostan Naturals édite l''intégralité des rapports d''analyses techniques exclusivement sous sa propre marque :
1. Télécharger la Fiche Technique de la Concrète (TDS) liée au SKU BNCON005
2. Télécharger le Certificat de Conformité des Cires Spécifique au Lot
3. Télécharger la Fiche de Données de Sécurité (FDS / MSDS) Conforme UE', 13);
INSERT INTO products (sku, category_key, name_fr, name_en, subtitle_fr, subtitle_en, inci, cas, origin, extraction_method_fr, extraction_method_en, short_description_fr, short_description_en, image, images, description_fr, specifications_fr, organoleptic_fr, regulatory_fr, quality_fr, confidentiality_fr, sort_order) VALUES ('BNCON006', 'concretes', 'Concrète de Basilic d''Égypte', 'Egyptian Basil Concrete', 'Le Bloc Aromatique Grand Vert – L''Essence Anisée Mère', 'The Great Green Aromatic Block – The Mother Aniseed Essence', 'Ocimum Basilicum Extract', '8015-73-4 / 84775-71-3', 'Égypte', 'Première extraction par solvants volatils organiques sur feuilles et sommités fraîches', 'Primary Extraction with Organic Volatile Solvents on Fresh Leaves and Tops', 'Extraite par solvants volatils à partir des sommités fleuries et des feuilles fraîches d''Ocimum basilicum cultivé sous le climat idéal de l''Égypte, notre Concrète de Basilic de Bostan Naturals est une matière première d''une puissance brute unique. Ce bloc cireux compact emprisonne les cires cuticulaires lourdes et les précieux éléments odorants thermosensibles de la plante. Il déploie un parfum d''une clarté fusante, frais, vert et herbacé, qui s''ouvre sur un cœur intensément épicé et anisé (estragole) aux nuances de réglisse douces. C''est la souche brute indispensable que notre usine utilise pour filtrer le précieux absolu de basilic destiné à la parfumerie fine.', 'Extracted with volatile solvents from the flowering tops and fresh leaves of Ocimum basilicum cultivated under Egypt''s ideal climate, our Bostan Naturals Basil Concrete is a raw material of unique brute power. This compact waxy block traps the heavy cuticular waxes and the precious heat-sensitive odorant elements of the plant. It unfolds a fragrance of melting clarity, fresh, green and herbaceous, opening on an intensely spicy and aniseed heart (estragole) with sweet liquorice nuances. It is the indispensable raw stock our factory uses to filter the precious basil absolute destined for fine perfumery.', '/images/categories/concretes.jpg', '[]', 'CONCRÈTE DE BASILIC D''ÉGYPTE
Le Bloc Aromatique Grand Vert – L''Essence Anisée Mère

Extraite par solvants volatils à partir des sommités fleuries et des feuilles fraîches d''Ocimum basilicum cultivé sous le climat idéal de l''Égypte, notre Concrète de Basilic de Bostan Naturals est une matière première d''une puissance brute unique. Ce bloc cireux compact emprisonne les cires cuticulaires lourdes et les précieux éléments odorants thermosensibles de la plante. Il déploie un parfum d''une clarté fusante, frais, vert et herbacé, qui s''ouvre sur un cœur intensément épicé et anisé (estragole) aux nuances de réglisse douces. C''est la souche brute indispensable que notre usine utilise pour filtrer le précieux absolu de basilic destiné à la parfumerie fine.', '["Nom INCI : Ocimum Basilicum Extract","Numéro CAS : 8015-73-4 / 84775-71-3","Code SKU : BNCON006","Source Botanique : Ocimum basilicum L. (Lamiaceae)","Origine : Égypte (100% Pure & Naturelle)","Procédé : Première extraction par solvants volatils organiques sur feuilles et sommités fraîches"]', '["Aspect : Masse solide cireuse à semi-solide compacte.","Couleur : Vert foncé à brun verdâtre profond.","Odeur : Très puissante, fraîche, intensément herbacée, épicée, aux facettes d''anis, de cire et de réglisse très denses caractéristiques du basilic égyptien.","Point de Fusion (Melting Point) : 45°C – 51°C","Solubilité : Insoluble dans l''eau, parfaitement soluble dans les solvants organiques et les huiles."]', 'Sécurité Moléculaire & Conformité REACH
La Concrète de Basilic Bostan Naturals garantit la protection naturelle de ses constituants volatils au cœur de sa matrice. Des analyses de contrôle sont réalisées pour vérifier l''authenticité et la qualité de chaque lot, et elle répond pleinement aux exigences de la réglementation européenne REACH pour les formulations de haute cosmétique.', 'Standard de Production : Processus d''extraction industrielle minutieusement régulé pour éviter les surchauffes, selon les plus strictes directives de management de la qualité.
Traçabilité Botanique Royale : Basilic cultivé et récolté localement, certifié 100% égyptien.
Contrôle Laboratoire : Les analyses sont réalisées selon les exigences du produit et du lot, auprès de laboratoires appropriés lorsque nécessaire.
Conditionnement de Transport Conforme aux Exigences Applicables : Expédié en conteneurs hermétiques professionnels scellés pour bloquer totalement l''air et préserver les précieuses facettes volatiles. Chaque unité est munie d''une étiquette technique standardisée de traçabilité (Sceau Bostan Naturals, SKU, Batch et Mentions légales).', 'Votre Traçabilité Commerciale sous Sceau de Confidentialité :
Pour préserver l''intégrité absolue de vos formules et garantir le secret commercial le plus strict concernant vos sources d''approvisionnement, chaque lot de Bostan Naturals est accompagné de son dossier réglementaire dédié, édité exclusivement sous notre nom de marque :
1. Télécharger la Fiche Technique de la Concrète (TDS) liée au SKU BNCON006
2. Télécharger le Certificat d''Analyse des Cires Mères Spécifique au Lot
3. Télécharger la Fiche de Données de Sécurité (FDS / MSDS) Conforme UE', 14);
INSERT INTO products (sku, category_key, name_fr, name_en, subtitle_fr, subtitle_en, inci, cas, origin, extraction_method_fr, extraction_method_en, short_description_fr, short_description_en, image, images, description_fr, specifications_fr, organoleptic_fr, regulatory_fr, quality_fr, confidentiality_fr, sort_order) VALUES ('BNCON007', 'concretes', 'Concrète de Petitgrain Bigarade d''Égypte', 'Egyptian Petitgrain Bigarade Concrete', 'Le Ciment Vert de l''Oranger – La Densité Ligneuse Flanquée de Fleur', 'The Green Cement of the Orange Tree – The Woody Density Flanked by Flower', 'Citrus Aurantium Amara Leaf/Twig Extract', '8014-17-3 / 72968-50-4', 'Égypte', 'Extraction primaire par solvants volatils sélectifs sur rameaux et feuilles fraîches', 'Primary Extraction with Selective Volatile Solvents on Fresh Twigs and Leaves', 'Obtenue par extraction par solvants à partir des feuilles et jeunes rameaux soigneusement sélectionnés du bigaradier en Égypte, notre Concrète de Petitgrain Bigarade de Bostan Naturals est une exclusivité industrielle hautement technique. Cette pâte solide cireuse concentre non seulement les huiles aromatiques volatiles des feuilles, mais également les cires cuticulaires lourdes et les traces de résines florales de l''arbre. Elle déploie un parfum d''une verdeur ligneuse amère, adoucie par des notes miellées de fleur d''oranger. C''est la souche brute non modifiée qui nous sert à façonner notre absolu de petitgrain de luxe.', 'Obtained by solvent extraction from the carefully selected leaves and young twigs of the bitter orange tree in Egypt, our Bostan Naturals Petitgrain Bigarade Concrete is a highly technical industrial exclusive. This solid waxy paste concentrates not only the volatile aromatic oils of the leaves, but also the heavy cuticular waxes and traces of the tree''s floral resins. It unfolds a fragrance of bitter woody greenness, softened by honeyed orange blossom notes. It is the unmodified raw stock we use to shape our luxury petitgrain absolute.', '/images/categories/concretes.jpg', '[]', 'CONCRÈTE DE PETITGRAIN BIGARADE D''ÉGYPTE
Le Ciment Vert de l''Oranger – La Densité Ligneuse Flanquée de Fleur

Obtenue par extraction par solvants à partir des feuilles et jeunes rameaux soigneusement sélectionnés du bigaradier en Égypte, notre Concrète de Petitgrain Bigarade de Bostan Naturals est une exclusivité industrielle hautement technique. Cette pâte solide cireuse concentre non seulement les huiles aromatiques volatiles des feuilles, mais également les cires cuticulaires lourdes et les traces de résines florales de l''arbre. Elle déploie un parfum d''une verdeur ligneuse amère, adoucie par des notes miellées de fleur d''oranger. C''est la souche brute non modifiée qui nous sert à façonner notre absolu de petitgrain de luxe.', '["Nom INCI : Citrus Aurantium Amara Leaf/Twig Extract","Numéro CAS : 8014-17-3 / 72968-50-4","Code SKU : BNCON007","Source Botanique : Citrus aurantium var. amara L. (Rutaceae)","Origine : Égypte (100% Pure & Naturelle)","Procédé : Extraction primaire par solvants volatils sélectifs sur rameaux et feuilles fraîches"]', '["Aspect : Masse solide cireuse compacte à semi-solide.","Couleur : Vert olive très foncé à brun verdâtre.","Odeur : Puissante, verte-amère, boisée, avec des facettes florales cireuses et des notes de foin élastiques et persistantes.","Point de Fusion (Melting Point) : 44°C – 51°C","Solubilité : Insoluble dans l''eau, hautement compatible avec les huiles et solvants de parfumerie."]', 'Protection Moléculaire et Traçabilité REACH
La Concrète de Petitgrain Bostan Naturals protège naturellement l''acétate de linalyle contre l''hydrolyse grâce à sa matrice cireuse anhydre. Ce produit technique de premier stade est entièrement validé conforme au règlement européen REACH, assurant une sécurité absolue pour le développement de cosmétiques solides et de parfums d''auteur.', 'Standard de Production : Extraction industrielle encadrée éliminant tout risque de surchauffe ou de dénaturation des terpènes, selon les plus strictes directives de management de la qualité.
Origine Égyptienne 100% Traçable : Rameaux issus exclusivement des tailles saisonnières de nos cultures contrôlées.
Contrôle Laboratoire : Les analyses sont réalisées selon les exigences du produit et du lot, auprès de laboratoires appropriés lorsque nécessaire.
Conditionnement de Transport Conforme aux Exigences Applicables : Expédié dans des conteneurs professionnels robustes, scellés hermétiquement, garantissant une protection maximale contre l''oxydation et les variations thermiques. Chaque unité est munie d''une étiquette technique standardisée de traçabilité (Sceau Bostan Naturals, SKU, Batch et Mentions légales).', 'Votre Traçabilité Commerciale sous Sceau de Confidentialité :
Pour préserver l''intégrité absolue de vos formules et garantir le secret commercial le plus strict concernant vos sources d''approvisionnement, chaque lot de Bostan Naturals est accompagné de son dossier réglementaire dédié, édité exclusivement sous notre nom de marque :
1. Télécharger la Fiche Technique de la Concrète (TDS) liée au SKU BNCON007
2. Télécharger le Certificat d''Analyse des Cires Mères Spécifique au Lot
3. Télécharger la Fiche de Données de Sécurité (FDS / MSDS) Conforme UE', 15);
INSERT INTO products (sku, category_key, name_fr, name_en, subtitle_fr, subtitle_en, inci, cas, origin, extraction_method_fr, extraction_method_en, short_description_fr, short_description_en, image, images, description_fr, specifications_fr, organoleptic_fr, regulatory_fr, quality_fr, confidentiality_fr, sort_order) VALUES ('BNCON008', 'concretes', 'Concrète de Jasmine Sambac d''Égypte', 'Egyptian Jasmine Sambac Concrete', 'La Cire Nocturne de l''Indole – L''Opulence Animale Brute', 'The Nocturnal Wax of Indole – The Raw Animalic Opulence', 'Jasminum Sambac Flower Cera', '91770-14-8 / 1034798-23-6', 'Égypte', 'Première extraction aux solvants volatils d''hydrocarbures légers sur fleurs fraîches', 'Primary Extraction with Light Hydrocarbon Volatile Solvents on Fresh Flowers', 'Issue du premier traitement des fleurs de Jasminum sambac récoltées à la tombée de la nuit dans nos domaines égyptiens, notre Concrète de Jasmin Sambac de Bostan Naturals est le paroxysme de la sensualité florale brute. Cette pâte solide cireuse retient l''intégralité des composés indoliques lourds, des cires cuticulaires et des pigments naturels de la fleur de فل. Elle déploie un parfum d''une force narcotique rare, plus vert, plus fruité et plus animal que le Grandiflorum. C''est le bloc de cire d''origine à partir duquel notre laboratory extrait l''absolu de sambac, garantissant une authenticité souveraine sans aucune manipulation extérieure.', 'Issued from the first processing of Jasminum sambac flowers harvested at nightfall in our Egyptian estates, our Bostan Naturals Jasmine Sambac Concrete is the paroxysm of raw floral sensuality. This solid waxy paste retains the entirety of the heavy indolic compounds, the cuticular waxes and the natural pigments of the flower of فل. It unfolds a fragrance of rare narcotic force, greener, fruitier and more animalic than Grandiflorum. It is the original block of wax from which our laboratory extracts the sambac absolute, guaranteeing sovereign authenticity without any external manipulation.', '/images/categories/concretes.jpg', '[]', 'CONCRÈTE DE JASMINE SAMBAC D''ÉGYPTE
La Cire Nocturne de l''Indole – L''Opulence Animale Brute

Issue du premier traitement des fleurs de Jasminum sambac récoltées à la tombée de la nuit dans nos domaines égyptiens, notre Concrète de Jasmin Sambac de Bostan Naturals est le paroxysme de la sensualité florale brute. Cette pâte solide cireuse retient l''intégralité des composés indoliques lourds, des cires cuticulaires et des pigments naturels de la fleur de فل. Elle déploie un parfum d''une force narcotique rare, plus vert, plus fruité et plus animal que le Grandiflorum. C''est le bloc de cire d''origine à partir duquel notre laboratory extrait l''absolu de sambac, garantissant une authenticité souveraine sans aucune manipulation extérieure.', '["Nom INCI : Jasminum Sambac Flower Cera","Numéro CAS : 91770-14-8 / 1034798-23-6","Code SKU : BNCON008","Source Botanique : Jasminum sambac (L.) Aiton","Origine : Égypte (100% Pure, Naturelle & Non altérée)","Procédé : Première extraction aux solvants volatils d''hydrocarbures légers sur fleurs fraîches"]', '["Aspect : Masse solide cireuse à semi-solide compacte.","Couleur : Orange foncé à brun rouge profond.","Odeur : Intensément florale blanche, lourde, hautement indolique, plus fruitée-verte et animale que le Grandiflorum.","Point de Fusion (Melting Point) : 46°C – 53°C","Solubilité : Insoluble dans l''eau, totalement soluble dans les solvants organiques gras, soluble à chaud dans l''alcool éthylique."]', 'Sécurité Moléculaire & Préservation des Anthranilates
La Concrète de Jasmin Sambac Bostan Naturals garantit la stabilisation des esters aromatiques complexes au cœur de ses cires végétales. Des analyses des solvants résiduels sont réalisées lorsque cela est applicable au produit et à son procédé d''extraction, et elle répond scrupuleusement aux critères du règlement REACH européen pour les matières de haute cosmétique.', 'Standard de Production : Processus d''extraction physique standardisé sous vide et température contrôlée, selon les plus strictes directives de management de la qualité.
Certification d''Origine Géographique : Fleurs de فل égyptien à 100% issues de nos filières contrôlées.
Contrôle Laboratoire : Les analyses sont réalisées selon les exigences du produit et du lot, auprès de laboratoires appropriés lorsque nécessaire.
Conditionnement de Transport Conforme aux Exigences Applicables : Expédié dans des conteneurs professionnels robustes, scellés hermétiquement, garantissant une protection maximale contre l''oxydation et les variations thermiques. Chaque unité est munie d''une étiquette technique standardisée de traçabilité (Sceau Bostan Naturals, SKU, Batch et Mentions légales).', 'Votre Traçabilité Commerciale sous Sceau de Confidentialité :
Pour préserver l''intégrité absolue de vos formules et garantir le secret commercial le plus strict concernant vos sources d''approvisionnement, chaque lot de Bostan Naturals est accompagné de son dossier réglementaire dédié, édité exclusivement sous notre nom de marque :
1. Télécharger la Fiche Technique de la Concrète (TDS) liée au SKU BNCON008
2. Télécharger le Rapport d''Authenticité de la Pâte Mère Spécifique au Lot
3. Télécharger la Fiche de Données de Sécurité (FDS / MSDS) Conforme UE', 16);
INSERT INTO products (sku, category_key, name_fr, name_en, subtitle_fr, subtitle_en, inci, cas, origin, extraction_method_fr, extraction_method_en, short_description_fr, short_description_en, image, images, description_fr, specifications_fr, organoleptic_fr, regulatory_fr, quality_fr, confidentiality_fr, sort_order) VALUES ('BNCON009', 'concretes', 'Concrète de Feuilles de Violette d''Égypte', 'Egyptian Violet Leaf Concrete', 'Le Bloc Vert Émeraude – La Force Cuirée Végétale à l''État Brut', 'The Emerald Green Block – The Raw Vegetable Leathery Force', 'Viola Odorata Leaf Cera', '8024-08-6 / 90131-42-3', 'Égypte', 'Extraction primaire par solvants organiques volatils à partir des feuilles fraîches', 'Primary Extraction with Volatile Organic Solvents from Fresh Leaves', 'L''Égypte dominant historiquement cette culture, notre Concrète de Feuilles de Violette de Bostan Naturals est le ciment végétal premier extrait à partir des feuilles fraîches de Viola odorata. Cette masse solide et compacte emprisonne les cires cuticulaires lourdes et toutes les chlorophylles de la feuille. Elle déploie un parfum d''une verdeur tranchante phénoménale, aux notes métalliques intenses et au fond de cuir chamoisé très prononcé. C''est la structure brute cireuse indispensable que notre usine utilise pour filtrer le précieux absolu de violette destiné aux plus grandes créations masculines et masculines-unisexe européennes.', 'Egypt historically dominating this culture, our Bostan Naturals Violet Leaf Concrete is the primary vegetable cement extracted from the fresh leaves of Viola odorata. This solid and compact mass traps the heavy cuticular waxes and all the chlorophylls of the leaf. It unfolds a fragrance of phenomenal cutting greenness, with intense metallic notes and a very pronounced suede leather base. It is the indispensable raw waxy structure that our factory uses to filter the precious violet absolute destined for the greatest European masculine and masculine-unisex creations.', '/images/categories/concretes.jpg', '[]', 'CONCRÈTE DE FEUILLES DE VIOLETTE D''ÉGYPTE
Le Bloc Vert Émeraude – La Force Cuirée Végétale à l''État Brut

L''Égypte dominant historiquement cette culture, notre Concrète de Feuilles de Violette de Bostan Naturals est le ciment végétal premier extrait à partir des feuilles fraîches de Viola odorata. Cette masse solide et compacte emprisonne les cires cuticulaires lourdes et toutes les chlorophylles de la feuille. Elle déploie un parfum d''une verdeur tranchante phénoménale, aux notes métalliques intenses et au fond de cuir chamoisé très prononcé. C''est la structure brute cireuse indispensable que notre usine utilise pour filtrer le précieux absolu de violette destiné aux plus grandes créations masculines et masculines-unisexe européennes.', '["Nom INCI : Viola Odorata Leaf Cera","Numéro CAS : 8024-08-6 / 90131-42-3","Code SKU : BNCON009","Source Botanique : Viola odorata L. (Violaceae)","Origine : Égypte (100% Pure, Naturelle & Pure Souche)","Procédé : Extraction primaire par solvants organiques volatils à partir des feuilles fraîches"]', '["Aspect : Masse solide dure, cireuse et très compacte (Hard waxy mass).","Couleur : Vert foncé profond, opaque, tendant vers le noir olive.","Odeur : Extrêmement puissante, herbeuse coupante, métallique (concombre froissé), avec un fond cuiré et terreux massif.","Point de Fusion (Melting Point) : 48°C – 55°C (Nécessite un chauffage modéré)","Solubilité : Insoluble dans l''eau, miscible avec les solvants organiques et cires végétales, soluble à chaud dans l''éthanol fort."]', 'Stabilité des Aldéhydes Verts & Conformité REACH
La Concrète de Feuilles de Violette Bostan Naturals stabilise les précieux aldéhydes et acides insaturés naturels (nonadiénal) contre l''oxydation de l''air grâce à sa gangue cireuse. Produit 100% naturel et tracé, il répond pleinement aux exigences de la réglementation européenne REACH.', 'Standard de Production : Contrôle strict de l''évaporation du solvant pour garantir un bloc de concrète dense et standardisé, selon les plus strictes directives de management de la qualité.
Approvisionnement Durable Garanti : Feuilles issues de récoltes écoresponsables sous contrôle exclusif.
Contrôle Laboratoire : Les analyses sont réalisées selon les exigences du produit et du lot, auprès de laboratoires appropriés lorsque nécessaire.
Conditionnement de Transport Conforme aux Exigences Applicables : Conditionné sous emballage professionnel hermétique pour bloquer totalement l''air et la lumière, protégeant ainsi les précieux éléments verts de l''oxydation. Chaque unité est munie d''une étiquette technique standardisée de traçabilité (Sceau Bostan Naturals, SKU, Batch et Mentions légales).', 'La Protection Intégrale de Vos Secrets d''Approvisionnement :
Pour préserver le secret le plus strict entourant vos approvisionnements en matières premières stratégiques, Bostan Naturals publie l''intégralité des documents techniques sous son propre sceau commercial :
1. Télécharger la Fiche Technique de la Concrète (TDS) liée au SKU BNCON009
2. Télécharger le Certificat de Conformité des Cires de Feuilles Spécifique au Lot
3. Télécharger la Fiche de Données de Sécurité (FDS / MSDS) Conforme UE', 17);
INSERT INTO products (sku, category_key, name_fr, name_en, subtitle_fr, subtitle_en, inci, cas, origin, extraction_method_fr, extraction_method_en, short_description_fr, short_description_en, image, images, description_fr, specifications_fr, organoleptic_fr, regulatory_fr, quality_fr, confidentiality_fr, sort_order) VALUES ('BNHE001', 'huiles-essentielles', 'Huile Essentielle de Néroli d''Égypte', 'Egyptian Neroli Essential Oil', 'La Quintessence de l''Élégance – L''Éclat Floral Vert Absolu', 'The Quintessence of Elegance – The Absolute Green Floral Radiance', 'Citrus Aurantium Amara Flower Oil', '8016-38-4 / 72968-50-4', 'Égypte', 'Distillation artisanale complète à la vapeur d''eau des fleurs fraîches', 'Complete Artisanal Steam Distillation of Fresh Flowers', 'Distillée à la vapeur d''eau à partir des pétales fraîchement cueillis du bigaradier (oranger amer) dans les vallées fertiles d''Égypte, notre Huile Essentielle de Néroli de Bostan Naturals est le symbole ultime de la fraîcheur aristocratique dans la parfumerie de niche. Cet élixir précieux déploie une signature olfactive aérienne, étincelante et d''une pureté cristalline. Il s''ouvre sur une envolée zestée d''agrumes et de notes vertes de sève, révélant un cœur floral blanc immaculé, à la fois propre, légèrement miellé et poudré, avant de s''épanouir sur un fond boisé-floral d''une finesse absolue. Un ingrédient de prestige incomparable pour apporter de la lumière, de la vibration et une distinction intemporelle aux structures de type Eaux de Cologne et Parfums Floraux de haute lignée.', 'Steam distilled from the freshly picked petals of the bitter orange tree in Egypt''s fertile valleys, our Bostan Naturals Neroli Essential Oil is the ultimate symbol of aristocratic freshness in niche perfumery. This precious elixir unfolds an aerial, sparkling olfactory signature of crystalline purity. It opens on a citrusy zesty burst and green sap notes, revealing an immaculate white floral heart, at once clean, slightly honeyed and powdery, before blossoming on a woody-floral base of absolute finesse. An incomparable prestige ingredient to bring light, vibration and timeless distinction to high-line Eau de Cologne and Floral Perfume structures.', '/images/categories/huiles-essentielles.jpg', '[]', 'HUILE ESSENTIELLE DE NÉROLI D''ÉGYPTE
La Quintessence de l''Élégance – L''Éclat Floral Vert Absolu

Distillée à la vapeur d''eau à partir des pétales fraîchement cueillis du bigaradier (oranger amer) dans les vallées fertiles d''Égypte, notre Huile Essentielle de Néroli de Bostan Naturals est le symbole ultime de la fraîcheur aristocratique dans la parfumerie de niche. Cet élixir précieux déploie une signature olfactive aérienne, étincelante et d''une pureté cristalline. Il s''ouvre sur une envolée zestée d''agrumes et de notes vertes de sève, révélant un cœur floral blanc immaculé, à la fois propre, légèrement miellé et poudré, avant de s''épanouir sur un fond boisé-floral d''une finesse absolue. Un ingrédient de prestige incomparable pour apporter de la lumière, de la vibration et une distinction intemporelle aux structures de type Eaux de Cologne et Parfums Floraux de haute lignée.', '["Nom INCI : Citrus Aurantium Amara Flower Oil","Numéro CAS : 8016-38-4 / 72968-50-4","Code SKU : BNHE001","Source Botanique : Citrus aurantium var. amara L. (Rutaceae)","Origine : Égypte (100% Pure & Naturelle)","Méthode d''Extraction : Distillation artisanale complète à la vapeur d''eau des fleurs fraîches"]', '["Aspect : Liquide mobile fluide.","Couleur : Jaune pâle à jaune ambré clair.","Odeur : Puissante, aérienne, florale fraîche, intensément zestée, aux accents verts et savonneux caractéristiques du néroli égyptien authentique.","Indice de Réfraction @ 20°C : 1.4630 – 1.4740","Densité Relative @ 20°C : 0.8640 – 0.8760","Pouvoir Rotatoire @ 20°C : +1.0° à +11.0°","Solubilité : Parfaitement soluble dans l''alcool éthylique (90%) et les huiles."]', 'Conformité Totale aux Normes Internationales & REACH
Chez Bostan Naturals, la rigueur réglementaire sécurise vos créations. Notre Huile Essentielle de Néroli est conforme aux exigences et restrictions applicables de l''IFRA pour l''utilisation prévue de la matière en parfumerie (la dernière mise à jour en vigueur) et répond pleinement aux exigences de la réglementation européenne REACH. Pour chaque expédition, nous suivons et calculons de manière dynamique les teneurs exactes en allergènes naturels volatils (notamment le linalol, le limonène, l''acétate de linalyle et le géraniol) afin de garantir une sécurité dermatologique absolue et de faciliter l''homologation de vos parfums finis en Catégorie 4 (Fine Fragrances).', 'Standard de Production : Suivi rigoureux des processus de distillation pour maintenir un profil olfactif constant sans fluctuations de lots, selon les plus strictes directives de management de la qualité.
Authenticité Égyptienne Garantie : Traçabilité totale depuis la cueillette printanière exclusive dans nos terroirs jusqu''au conditionnement final.
Contrôle Laboratoire : Les analyses sont réalisées selon les exigences du produit et du lot, auprès de laboratoires appropriés lorsque nécessaire.
Conditionnement de Transport Conforme aux Exigences Applicables : Expédié dans des flacons en aluminium blindés et étanches, protégeant le produit de l''oxydation thermique et garantissant la sécurité lors du transport international. Chaque unité est munie d''une étiquette technique standardisée de traçabilité (Sceau Bostan Naturals, SKU, Batch et Mentions légales).', 'Votre Traçabilité Commerciale sous Sceau de Confidentialité :
Pour préserver l''intégrité de vos formules et garantir le secret commercial le plus strict concernant vos sources d''approvisionnement, chaque lot de Bostan Naturals est accompagné de son dossier réglementaire dédié, édité exclusivement sous notre nom de marque :
1. Télécharger l''exemple de profil GC-MS (Empreinte chromatographique certifiant la pureté à 100%)
2. Télécharger le Certificat d''Analyse (COA) Spécifique au Lot lié au SKU BNHE001
3. Télécharger la Fiche de Données de Sécurité (FDS / MSDS) Conforme UE', 18);
INSERT INTO products (sku, category_key, name_fr, name_en, subtitle_fr, subtitle_en, inci, cas, origin, extraction_method_fr, extraction_method_en, short_description_fr, short_description_en, image, images, description_fr, specifications_fr, organoleptic_fr, regulatory_fr, quality_fr, confidentiality_fr, sort_order) VALUES ('BNHE002', 'huiles-essentielles', 'Huile Essentielle de Petitgrain Bigarade d''Égypte', 'Egyptian Petitgrain Bigarade Essential Oil', 'L''Or Vert des Feuilles – L''Énergie Boisée de la Pluie', 'The Green Gold of Leaves – The Woody Energy of the Rain', 'Citrus Aurantium Amara Leaf/Twig Oil', '8014-17-3 / 72968-50-4', 'Égypte', 'Distillation complète à la vapeur d''eau des feuilles et jeunes rameaux fraîchement coupés', 'Complete Steam Distillation of Freshly Cut Leaves and Young Twigs', 'Distillée à partir des feuilles vertes et des jeunes rameaux du bigaradier (oranger amer) soigneusement taillés en Égypte, notre Huile Essentielle de Petitgrain Bigarade de Bostan Naturals est un pilier de caractère pour la parfumerie de niche. Cet élixir offre une signature olfactive d''une fraîcheur sauvage et d''une intensité texturée. Il se caractérise par une attaque verte, vive et hépatique, qui évolue vers un cœur floral discret rappelant la fleur d''oranger, magnifié par un fond boisé, herbacé, amer et boisé-sombre qui évoque l''odeur de la terre après la pluie. Un composant d''architecture essentiel pour insuffler du relief, de la masculinité élégante, de la tension et une tenue nerveuse aux structures Fougères, Boisées et aux Colognes modernes.', 'Distilled from the green leaves and young twigs of the bitter orange tree carefully pruned in Egypt, our Bostan Naturals Petitgrain Bigarade Essential Oil is a cornerstone of character for niche perfumery. This elixir offers an olfactory signature of wild freshness and textured intensity. It is characterized by a green, vivid and sharp attack, evolving towards a discreet floral heart reminiscent of orange blossom, magnified by a woody, herbaceous, bitter and dark-woody base that evokes the smell of the earth after the rain. An essential architectural component to breathe relief, elegant masculinity, tension and nervy hold into Fougère, Woody structures and modern Colognes.', '/images/categories/huiles-essentielles.jpg', '[]', 'HUILE ESSENTIELLE DE PETITGRAIN BIGARADE D''ÉGYPTE
L''Or Vert des Feuilles – L''Énergie Boisée de la Pluie

Distillée à partir des feuilles vertes et des jeunes rameaux du bigaradier (oranger amer) soigneusement taillés en Égypte, notre Huile Essentielle de Petitgrain Bigarade de Bostan Naturals est un pilier de caractère pour la parfumerie de niche. Cet élixir offre une signature olfactive d''une fraîcheur sauvage et d''une intensité texturée. Il se caractérise par une attaque verte, vive et hépatique, qui évolue vers un cœur floral discret rappelant la fleur d''oranger, magnifié par un fond boisé, herbacé, amer et boisé-sombre qui évoque l''odeur de la terre après la pluie. Un composant d''architecture essentiel pour insuffler du relief, de la masculinité élégante, de la tension et une tenue nerveuse aux structures Fougères, Boisées et aux Colognes modernes.', '["Nom INCI : Citrus Aurantium Amara Leaf/Twig Oil","Numéro CAS : 8014-17-3 / 72968-50-4","Code SKU : BNHE002","Source Botanique : Citrus aurantium var. amara L. (Rutaceae)","Origine : Égypte (100% Pure & Naturelle)","Méthode d''Extraction : Distillation complète à la vapeur d''eau des feuilles et jeunes rameaux fraîchement coupés"]', '["Aspect : Liquide mobile fluide très limpide.","Couleur : Jaune clair à jaune-vert pâle.","Odeur : Fraîche, verte, herbacée, amère, avec des nuances boisées et des sous-tons floraux subtils.","Indice de Réfraction @ 20°C : 1.4600 – 1.4720","Densité Relative @ 20°C : 0.8800 – 0.8990","Pouvoir Rotatoire @ 20°C : -5.0° à +1.0°","Solubilité : Parfaitement soluble dans l''alcool éthylique fort et les huiles de support."]', 'Conformité Totale & Traçabilité Européenne
Chez Bostan Naturals, la perfection technique est garantie. Notre Huile Essentielle de Petitgrain Bigarade est conforme aux exigences et restrictions applicables de l''IFRA pour l''utilisation prévue de la matière en parfumerie (la dernière mise à jour en vigueur) et répond scrupuleusement au protocole européen REACH. Nous suivons de près les concentrations naturelles d''allergènes volatils (comme l''acétate de linalyle, le linalol, le géraniol et le limonène) afin d''assurer une traçabilité irréprochable et de simplifier vos démarches de validation toxicologique sur le marché européen en Catégorie 4 (Fine Fragrances).', 'Standard de Production : Suivi rigoureux de la chaîne de distillation pour éliminer toute variation organoleptique ou physique, selon les plus strictes directives de management de la qualité.
Qualité Botanique Garantie : Feuilles issues exclusivement de cultures contrôlées et sélectionnées à la main dans nos terroirs.
Contrôle Laboratoire : Les analyses sont réalisées selon les exigences du produit et du lot, auprès de laboratoires appropriés lorsque nécessaire.
Conditionnement de Transport Conforme aux Exigences Applicables : Expédié dans des flacons ou conteneurs en aluminium professionnels étanches pour sécuriser l''expédition internationale et empêcher la dégradation des terpènes volatils. Chaque unité est munie d''une étiquette technique standardisée de traçabilité (Sceau Bostan Naturals, SKU, Batch et Mentions légales).', 'La Préservation de Votre Indépendance Commerciale :
Chaque lot livré par Bostan Naturals est accompagné de son propre dossier de conformité, garantissant que vous restez le seul maître à bord concernant l''origine et le secret de vos ingrédients stratégiques :
1. Télécharger l''exemple de profil GC-MS (Analyse chromatographique d''authenticité 100%)
2. Télécharger le Certificat d''Analyse (COA) Spécifique au Lot lié au SKU BNHE002
3. Télécharger la Fiche de Données de Sécurité (FDS / MSDS) Conforme UE', 19);
INSERT INTO products (sku, category_key, name_fr, name_en, subtitle_fr, subtitle_en, inci, cas, origin, extraction_method_fr, extraction_method_en, short_description_fr, short_description_en, image, images, description_fr, specifications_fr, organoleptic_fr, regulatory_fr, quality_fr, confidentiality_fr, sort_order) VALUES ('BNHE003', 'huiles-essentielles', 'Huile Essentielle de Géranium d''Égypte', 'Egyptian Geranium Essential Oil', 'La Vibrance Florale – L''Éclat Rosé aux Accents Verts et Épicés', 'The Floral Vibrance – The Rosy Radiance with Green and Spicy Accents', 'Pelargonium Graveolens Flower Oil (ou Pelargonium Graveolens Oil)', '90082-51-2 / 8000-46-2', 'Égypte', 'Distillation complète à la vapeur d''eau des parties aériennes fraîches', 'Complete Steam Distillation of Fresh Aerial Parts', 'Distillée avec un savoir-faire traditionnel à partir des feuilles et des tiges fraîches de Pelargonium graveolens cultivées dans les terroirs d''exception en Égypte, notre Huile Essentielle de Géranium de Bostan Naturals est le pilier commercial incontournable de la parfumerie fine. Cet élixir dynamique et facetté offre une alternative d''une richesse inouïe à l''essence de rose, prisée par les plus grands créateurs de niche. Il déploie une signature olfactive hautement sophistiquée : une envolée vive, herbacée et subtilement fruitée, qui s''ouvre sur un cœur floral intensément rosé, magnifié par des éclats de menthe poivrée, des nuances de litchi et un fond balsamique légèrement terreux d''une élégance rare. Un ingrédient architectural indispensable pour insuffler du relief, de la fraîcheur et une tenue magistrale aux structures Florales, Fougères et Chyprées.', 'Distilled with traditional know-how from the fresh leaves and stems of Pelargonium graveolens cultivated in the exceptional terroirs of Egypt, our Bostan Naturals Geranium Essential Oil is the essential commercial pillar of fine perfumery. This dynamic and faceted elixir offers an alternative of unheard-of richness to rose essence, prized by the greatest niche creators. It unfolds a highly sophisticated olfactory signature: a vivid, herbaceous and subtly fruity burst, opening on an intensely rosy floral heart, magnified by peppermint flashes, lychee nuances and a slightly earthy balsamic base of rare elegance. An indispensable architectural ingredient to breathe relief, freshness and masterful hold into Floral, Fougère and Chypre structures.', '/images/categories/huiles-essentielles.jpg', '[]', 'HUILE ESSENTIELLE DE GÉRANIUM D''ÉGYPTE
La Vibrance Florale – L''Éclat Rosé aux Accents Verts et Épicés

Distillée avec un savoir-faire traditionnel à partir des feuilles et des tiges fraîches de Pelargonium graveolens cultivées dans les terroirs d''exception en Égypte, notre Huile Essentielle de Géranium de Bostan Naturals est le pilier commercial incontournable de la parfumerie fine. Cet élixir dynamique et facetté offre une alternative d''une richesse inouïe à l''essence de rose, prisée par les plus grands créateurs de niche. Il déploie une signature olfactive hautement sophistiquée : une envolée vive, herbacée et subtilement fruitée, qui s''ouvre sur un cœur floral intensément rosé, magnifié par des éclats de menthe poivrée, des nuances de litchi et un fond balsamique légèrement terreux d''une élégance rare. Un ingrédient architectural indispensable pour insuffler du relief, de la fraîcheur et une tenue magistrale aux structures Florales, Fougères et Chyprées.', '["Nom INCI : Pelargonium Graveolens Flower Oil (ou Pelargonium Graveolens Oil)","Numéro CAS : 90082-51-2 / 8000-46-2","Code SKU : BNHE003","Source Botanique : Pelargonium graveolens L''Hér. (Geraniaceae)","Origine : Égypte (100% Pure & Naturelle)","Méthode d''Extraction : Distillation complète à la vapeur d''eau des parties aériennes fraîches"]', '["Aspect : Liquide mobile fluide très limpide.","Couleur : Jaune ambré clair à vert pâle transparent.","Odeur : Puissante, florale-rosée intense, aux facettes vertes, menthées et subtilement épicées caractéristiques du géranium égyptien authentique.","Indice de Réfraction @ 20°C : 1.4610 – 1.4720","Densité Relative @ 20°C : 0.8840 – 0.9010","Pouvoir Rotatoire @ 20°C : -14.0° à -7.0°","Solubilité : Parfaitement soluble dans l''alcool éthylique fort et les huiles de support."]', 'Conformité Totale aux Normes Internationales & REACH
Chez Bostan Naturals, l''excellence technique protège votre liberté créative. Notre Huile Essentielle de Géranium Égyptien est conforme aux exigences et restrictions applicables de l''IFRA pour l''utilisation prévue de la matière en parfumerie (la dernière mise à jour en vigueur) et répond pleinement aux exigences de la réglementation européenne REACH. Pour chaque expédition, nous suivons et calculons de manière dynamique les teneurs exactes en allergènes naturels volatils (notamment le citronellol, le géraniol, le linalol, le citral et le limonène) afin de garantir une sécurité dermatologique absolue et de faciliter l''évaluation réglementaire et la formulation de vos parfums finis en Catégorie 4 (Fine Fragrances).', 'Standard de Production : Suivi strict des processus de distillation pour une standardisation parfaite du profil aromatique d''un lot à l''autre, selon les plus strictes directives de management de la qualité.
Authenticité Égyptienne Garantie : Traçabilité totale depuis les champs de récolte contrôlés jusqu''au conditionnement final.
Contrôle Laboratoire : Les analyses sont réalisées selon les exigences du produit et du lot, auprès de laboratoires appropriés lorsque nécessaire.
Conditionnement de Transport Conforme aux Exigences Applicables : Expédié dans des conteneurs en aluminium professionnels blindés et scellés, garantissant une protection maximale contre l''oxydation thermique lors du transport international. Chaque unité est munie d''une étiquette technique standardisée de traçabilité (Sceau Bostan Naturals, SKU, Batch et Mentions légales).', 'La Garantie Absolue de Votre Secret Commercial :
Pour préserver l''intégrité de vos formules et masquer l''identité de vos fournisseurs stratégiques, Bostan Naturals édite l''intégralité des rapports d''analyses techniques exclusivement sous sa propre marque :
1. Télécharger l''exemple de profil GC-MS (Empreinte chromatographique certifiant la pureté à 100%)
2. Télécharger le Certificat d''Analyse (COA) Spécifique au Lot lié au SKU BNHE003
3. Télécharger la Fiche de Données de Sécurité (FDS / MSDS) Conforme UE', 20);
INSERT INTO products (sku, category_key, name_fr, name_en, subtitle_fr, subtitle_en, inci, cas, origin, extraction_method_fr, extraction_method_en, short_description_fr, short_description_en, image, images, description_fr, specifications_fr, organoleptic_fr, regulatory_fr, quality_fr, confidentiality_fr, sort_order) VALUES ('BNHE004', 'huiles-essentielles', 'Huile Essentielle de Camomille Bleue d''Égypte', 'Egyptian Blue Chamomile Essential Oil', 'L''Élixir d''Encre Sacré – La Signature Audacieuse de la Parfumerie d''Auteur', 'The Sacred Ink Elixir – The Bold Signature of Author Perfumery', 'Chamomilla Recutita Flower Oil (ou Matricaria Recutita Flower Oil)', '8002-66-2 / 84082-60-0', 'Égypte', 'Distillation rigoureuse à la vapeur d''eau des capitules floraux séchés', 'Rigorous Steam Distillation of Dried Floral Heads', 'Distillée à partir des fleurs de camomille matricaire cultivées avec soin en Égypte, notre Huile Essentielle de Camomille Bleue de Bostan Naturals est un chef-d''œuvre de distinction visuelle et olfactive pour la parfumerie de niche. Cet élixir extraordinaire, caractérisé par sa couleur bleu encre fascinante due à sa richesse naturelle en chamazulène, offre une signature hautement artistique. Il déploie un profil olfactif d''une complexité envoûtante : une attaque herbeuse et fruitée de pomme mûre, qui s''ouvre sur un cœur chaud, doux, intensément aromatique, et un fond terreux, balsamique-foin aux nuances mystiques évoquant le tabac blond de luxe. Un ingrédient d''avant-garde d''une force chromatique et olfactive rare, indispensable pour signer les créations boisées, ambrées et aromatiques les plus audacieuses.', 'Distilled from the flowers of chamomile matricaria carefully cultivated in Egypt, our Bostan Naturals Blue Chamomile Essential Oil is a masterpiece of visual and olfactory distinction for niche perfumery. This extraordinary elixir, characterized by its fascinating ink-blue color due to its natural richness in chamazulene, offers a highly artistic signature. It unfolds an olfactory profile of enchanting complexity: a herbaceous and ripe apple attack, opening on a warm, sweet, intensely aromatic heart, and an earthy, balsamic-hay base with mystical nuances evoking luxury blond tobacco. An avant-garde ingredient of rare chromatic and olfactory force, indispensable for signing the most audacious woody, ambery and aromatic creations.', '/images/categories/huiles-essentielles.jpg', '[]', 'HUILE ESSENTIELLE DE CAMOMILLE BLEUE D''ÉGYPTE
L''Élixir d''Encre Sacré – La Signature Audacieuse de la Parfumerie d''Auteur

Distillée à partir des fleurs de camomille matricaire cultivées avec soin en Égypte, notre Huile Essentielle de Camomille Bleue de Bostan Naturals est un chef-d''œuvre de distinction visuelle et olfactive pour la parfumerie de niche. Cet élixir extraordinaire, caractérisé par sa couleur bleu encre fascinante due à sa richesse naturelle en chamazulène, offre une signature hautement artistique. Il déploie un profil olfactif d''une complexité envoûtante : une attaque herbeuse et fruitée de pomme mûre, qui s''ouvre sur un cœur chaud, doux, intensément aromatique, et un fond terreux, balsamique-foin aux nuances mystiques évoquant le tabac blond de luxe. Un ingrédient d''avant-garde d''une force chromatique et olfactive rare, indispensable pour signer les créations boisées, ambrées et aromatiques les plus audacieuses.', '["Nom INCI : Chamomilla Recutita Flower Oil (ou Matricaria Recutita Flower Oil)","Numéro CAS : 8002-66-2 / 84082-60-0","Code SKU : BNHE004","Source Botanique : Matricaria recutita L. / Matricaria chamomilla (Asteraceae)","Origine : Égypte (100% Pure & Naturelle)","Méthode d''Extraction : Distillation rigoureuse à la vapeur d''eau des capitules floraux séchés"]', '["Aspect : Liquide mobile fluide, légèrement visqueux avec le temps.","Couleur : Bleu d''encre profond, bleu nuit intense (dû à la formation de chamazulène pendant la distillation).","Odeur : Puissante, aromatique, herbacée-douce, aux facettes fruitées, fruitées-pomme et aux sous-tons chauds de foin et de tabac.","Indice de Réfraction @ 20°C : 1.4800 – 1.5100","Densité Relative @ 20°C : 0.9100 – 0.9550","Solubilité : Parfaitement soluble dans l''alcool éthylique fort et les huiles de support."]', 'Conformité Totale aux Exigences Européennes & REACH
Chez Bostan Naturals, la sécurité moléculaire valide votre génie créatif. Notre Huile Essentielle de Camomille Bleue est conforme aux exigences et restrictions applicables de l''IFRA pour l''utilisation prévue de la matière en parfumerie (la dernière mise à jour en vigueur) et s''aligne pleinement avec les exigences REACH de l''Union Européenne. Nous suivons de près ses constituants actifs (comme l''alpha-bisabolol et les oxydes de bisabolol) par chromatographie, garantissant une matière brute d''une pureté chirurgicale et une sécurité dermatologique absolue pour la formulation en Catégorie 4 (Fine Fragrances).', 'Standard de Production : Processus de distillation minutieusement régulé pour préserver le taux de Chamazulène et éviter les variations de couleur ou d''odeur, selon les plus strictes directives de management de la qualité.
Qualité Botanique Certifiée : Sélection rigoureuse de matricaires locales pour une traçabilité sans faille depuis la récolte.
Contrôle Laboratoire : Les analyses sont réalisées selon les exigences du produit et du lot, auprès de laboratoires appropriés lorsque nécessaire.
Conditionnement de Transport Conforme aux Exigences Applicables : Conditionné en flacons d''aluminium épais hermétiques pour bloquer totalement la lumière et l''air, empêchant la décoloration naturelle du pigment bleu. Chaque unité est munie d''une étiquette technique standardisée de traçabilité (Sceau Bostan Naturals, SKU, Batch et Mentions légales).', 'Votre Indépendance Commerciale sous Haute Protection :
Afin de protéger vos secrets de fabrication et de dissimuler l''origine de vos intrants stratégiques, Bostan Naturals publie l''intégralité de la documentation de traçabilité exclusivement sous son identité corporative :
1. Télécharger l''exemple de profil GC-MS (Preuve de pureté et dosage du Chamazulène)
2. Télécharger le Certificat d''Analyse (COA) Spécifique au Lot lié au SKU BNHE004
3. Télécharger la Fiche de Données de Sécurité (FDS / MSDS) Conforme UE', 21);
INSERT INTO products (sku, category_key, name_fr, name_en, subtitle_fr, subtitle_en, inci, cas, origin, extraction_method_fr, extraction_method_en, short_description_fr, short_description_en, image, images, description_fr, specifications_fr, organoleptic_fr, regulatory_fr, quality_fr, confidentiality_fr, sort_order) VALUES ('BNHE005', 'huiles-essentielles', 'Huile Essentielle de Marjolaine d''Égypte', 'Egyptian Marjoram Essential Oil', 'L''Apothicaire Royal – La Chaleur Aromatique aux Accents Épicés Doux', 'The Royal Apothecary – The Aromatic Warmth with Sweet Spicy Accents', 'Origanum Majorana Flower Oil (ou Origanum Majorana Leaf Oil)', '8015-01-8 / 84082-58-6', 'Égypte', 'Distillation complète à la vapeur d''eau des sommités fleuries fraîches', 'Complete Steam Distillation of Fresh Flowering Tops', 'Distillée à la vapeur d''eau à partir des sommités fleuries de Majorana hortensis cultivées dans le terroir d''exception égyptien, notre Huile Essentielle de Marjolaine de Bostan Naturals est d''une finesse thérapeutique et olfactive rare, mondialement réputée. Ce joyau aromatique déploie une signature olfactive d''une tiédeur enveloppante : une envolée fraîche et herbacée qui s''ouvre rapidement sur un cœur intensément boisé, doux et camphré, rehaussé de facettes épicées rappelant la cardamome et la noix de muscade. Un ingrédient d''apothicaire d''une élégance vintage indispensable pour structurer, adoucir et apporter un relief aromatique noble aux compositions masculines, boisées, et aux notes de tête des créations de niche.', 'Steam distilled from the flowering tops of Majorana hortensis cultivated in the exceptional Egyptian terroir, our Bostan Naturals Marjoram Essential Oil is of rare therapeutic and olfactory finesse, world-renowned. This aromatic jewel unfolds an olfactory signature of enveloping warmth: a fresh and herbaceous burst that quickly opens on an intensely woody, sweet and camphorated heart, enhanced by spicy facets reminiscent of cardamom and nutmeg. An apothecary ingredient of vintage elegance indispensable for structuring, softening and bringing a noble aromatic relief to masculine, woody compositions and the top notes of niche creations.', '/images/categories/huiles-essentielles.jpg', '[]', 'HUILE ESSENTIELLE DE MARJOLAINE D''ÉGYPTE
L''Apothicaire Royal – La Chaleur Aromatique aux Accents Épicés Doux

Distillée à la vapeur d''eau à partir des sommités fleuries de Majorana hortensis cultivées dans le terroir d''exception égyptien, notre Huile Essentielle de Marjolaine de Bostan Naturals est d''une finesse thérapeutique et olfactive rare, mondialement réputée. Ce joyau aromatique déploie une signature olfactive d''une tiédeur enveloppante : une envolée fraîche et herbacée qui s''ouvre rapidement sur un cœur intensément boisé, doux et camphré, rehaussé de facettes épicées rappelant la cardamome et la noix de muscade. Un ingrédient d''apothicaire d''une élégance vintage indispensable pour structurer, adoucir et apporter un relief aromatique noble aux compositions masculines, boisées, et aux notes de tête des créations de niche.', '["Nom INCI : Origanum Majorana Flower Oil (ou Origanum Majorana Leaf Oil)","Numéro CAS : 8015-01-8 / 84082-58-6","Code SKU : BNHE005","Source Botanique : Origanum marjorana L. / Majorana hortensis Moench (Lamiaceae)","Origine : Égypte (100% Pure & Naturelle)","Méthode d''Extraction : Distillation complète à la vapeur d''eau des sommités fleuries fraîches"]', '["Aspect : Liquide mobile fluide.","Couleur : Jaune pâle à jaune-vert clair transparent.","Odeur : Puissante, aromatique, herbacée, chaude, boisée-épicée douce, avec des sous-tons camphrés subtils caractéristiques de la marjolaine égyptienne.","Indice de Réfraction @ 20°C : 1.4700 – 1.4760","Densité Relative @ 20°C : 0.8900 – 0.9060","Pouvoir Rotatoire @ 20°C : +14.0° à +25.0°","Solubilité : Parfaitement soluble dans l''alcool éthylique et les huiles végétales."]', 'Sécurité Avancée & Conformité IFRA
Chez Bostan Naturals, l''excellence réglementaire protège votre marque. Notre Huile Essentielle de Marjolaine est conforme aux exigences et restrictions applicables de l''IFRA pour l''utilisation prévue de la matière en parfumerie (la dernière mise à jour en vigueur) et s''aligne pleinement avec les exigences REACH. Nous suivons de près ses constituants moléculaires par chromatographie (notamment le terpinène-4-ol, le gamma-terpinène et le linalol) afin d''assurer une traçabilité irréprochable et de simplifier vos démarches de validation toxicologique en Europe pour la formulation en Catégorie 4 (Fine Fragrances).', 'Standard de Production : Suivi rigoureux de la chaîne de distillation pour éliminer toute variation du profil terpénique d''un lot à l''autre, selon les plus strictes directives de management de la qualité.
Traçabilité Agricole Garantie : Récolte effectuée à maturité idéale dans nos terroirs dédiés pour un produit final d''une qualité optimale.
Contrôle Laboratoire : Les analyses sont réalisées selon les exigences du produit et du lot, auprès de laboratoires appropriés lorsque nécessaire.
Conditionnement de Transport Conforme aux Exigences Applicables : Expédié en flacons d''aluminium étanches professionnels pour bloquer l''air et préserver les facettes aromatiques délicates. Chaque unité est munie d''une étiquette technique standardisée de traçabilité (Sceau Bostan Naturals, SKU, Batch et Mentions légales).', 'Votre Indépendance Commerciale sous Haute Protection :
Afin de protéger vos secrets industriels et de masquer l''identité de vos fournisseurs stratégiques, Bostan Naturals publie toute la documentation de traçabilité exclusivement sous son identity corporative :
1. Télécharger l''exemple de profil GC-MS (Analyse chromatographique d''authenticité)
2. Télécharger le Certificat d''Analyse (COA) Spécifique au Lot lié au SKU BNHE005
3. Télécharger la Fiche de Données de Sécurité (FDS / MSDS) Conforme UE', 22);
INSERT INTO products (sku, category_key, name_fr, name_en, subtitle_fr, subtitle_en, inci, cas, origin, extraction_method_fr, extraction_method_en, short_description_fr, short_description_en, image, images, description_fr, specifications_fr, organoleptic_fr, regulatory_fr, quality_fr, confidentiality_fr, sort_order) VALUES ('BNHE006', 'huiles-essentielles', 'Huile Essentielle de Graines de Coriandre d''Égypte', 'Egyptian Coriander Seed Essential Oil', 'La Fraîcheur Lumineuse – Le Frisson Épicé, Boisé et Éclatant', 'The Luminous Freshness – The Spicy, Woody and Radiant Shiver', 'Coriandrum Sativum Fruit Oil (ou Coriandrum Sativum Seed Oil)', '8008-52-4 / 84775-50-8', 'Égypte', 'Distillation complète à la vapeur d''eau des graines séchées et broyées', 'Complete Steam Distillation of Dried and Ground Seeds', 'Distillée à partir des graines mûres de Coriandrum sativum cultivées sous le soleil généreux d''Égypte, notre Huile Essentielle de Coriandre Graines de Bostan Naturals est un joyau de dynamisme pour la parfumerie fine. Cet élixir offre une signature olfactive d''une clarté fusante et d''une vibration exceptionnelle. Très riche en linalol naturel, il s''ouvre sur une attaque épicée fraîche, poivrée et intensément zestée, révélant un cœur boisé doux aux facettes florales subtiles (rappelant le freesia) et un fond aromatique texturé d''une grande persistance. Un ingrédient d''avant-garde indispensable pour ouvrir les notes de tête et apporter une luminosité moderne, de l''envolée et de la clarté aux compositions Boisées, Ambrées et aux Colognes de niche.', 'Distilled from the ripe seeds of Coriandrum sativum cultivated under Egypt''s generous sun, our Bostan Naturals Coriander Seed Essential Oil is a jewel of dynamism for fine perfumery. This elixir offers an olfactory signature of melting clarity and exceptional vibration. Very rich in natural linalool, it opens on a fresh, peppery and intensely zesty spicy attack, revealing a soft woody heart with subtle floral facets (reminiscent of freesia) and a textured aromatic base of great persistence. An indispensable avant-garde ingredient to open the top notes and bring modern luminosity, lift and clarity to Woody, Ambery compositions and niche Colognes.', '/images/categories/huiles-essentielles.jpg', '[]', 'HUILE ESSENTIELLE DE GRAINES DE CORIANDRE D''ÉGYPTE
La Fraîcheur Lumineuse – Le Frisson Épicé, Boisé et Éclatant

Distillée à partir des graines mûres de Coriandrum sativum cultivées sous le soleil généreux d''Égypte, notre Huile Essentielle de Coriandre Graines de Bostan Naturals est un joyau de dynamisme pour la parfumerie fine. Cet élixir offre une signature olfactive d''une clarté fusante et d''une vibration exceptionnelle. Très riche en linalol naturel, il s''ouvre sur une attaque épicée fraîche, poivrée et intensément zestée, révélant un cœur boisé doux aux facettes florales subtiles (rappelant le freesia) et un fond aromatique texturé d''une grande persistance. Un ingrédient d''avant-garde indispensable pour ouvrir les notes de tête et apporter une luminosité moderne, de l''envolée et de la clarté aux compositions Boisées, Ambrées et aux Colognes de niche.', '["Nom INCI : Coriandrum Sativum Fruit Oil (ou Coriandrum Sativum Seed Oil)","Numéro CAS : 8008-52-4 / 84775-50-8","Code SKU : BNHE006","Source Botanique : Coriandrum sativum L. (Apiaceae)","Origine : Égypte (100% Pure & Naturelle)","Méthode d''Extraction : Distillation complète à la vapeur d''eau des graines séchées et broyées"]', '["Aspect : Liquide mobile fluide très limpide.","Couleur : Incolore à jaune très pâle.","Odeur : Puissante, fraîche, épicée-boisée, zestée, avec une note florale douce caractéristique de la graine de coriandre égyptienne.","Indice de Réfraction @ 20°C : 1.4620 – 1.4700","Densité Relative @ 20°C : 0.8600 – 0.8800","Pouvoir Rotatoire @ 20°C : +8.0° à +15.0°","Solubilité : Parfaitement soluble dans l''alcool éthylique fort et les huiles."]', 'Conformité Totale aux Exigences Européennes & REACH
Chez Bostan Naturals, la rigueur technique est le bouclier de votre créativité. Notre Huile Essentielle de Coriandre Graines est conforme aux exigences et restrictions applicables de l''IFRA pour l''utilisation prévue de la matière en parfumerie (la dernière mise à jour en vigueur) et répond pleinement aux exigences de la réglementation européenne REACH. Pour chaque lot, nous suivons de près les teneurs naturelles en allergènes volatils (notamment le linalol, le géraniol et le limonène) afin d''assurer une sécurité dermatologique absolue et de faciliter l''évaluation réglementaire et la formulation de vos formules en Catégorie 4 (Fine Fragrances).', 'Standard de Production : Processus de distillation minutieusement standardisé pour éviter les variations du profil olfactif et garantir un taux de linalol optimal, selon les plus strictes directives de management de la qualité.
Authenticité Botanique Garantie : Graines issues exclusivement de cultures contrôlées et tracées depuis la récolte.
Contrôle Laboratoire : Les analyses sont réalisées selon les exigences du produit et du lot, auprès de laboratoires appropriés lorsque nécessaire.
Conditionnement de Transport Conforme aux Exigences Applicables : Expédié en flacons d''aluminium épais hermétiques pour bloquer totalement l''air et préserver les précieuses facettes volatiles. Chaque unité est munie d''une étiquette technique standardisée de traçabilité (Sceau Bostan Naturals, SKU, Batch et Mentions légales).', 'La Garantie du Secret Commercial de Vos Formules :
Chaque livraison de Bostan Naturals est accompagnée de son dossier réglementaire dédié, édité exclusivement sous notre nom de marque pour protéger la confidentialité de vos sources :
1. Télécharger l''exemple de profil GC-MS (Empreinte chromatographique certifiant la pureté à 100%)
2. Télécharger le Certificat d''Analyse (COA) Spécifique au Lot lié au SKU BNHE006
3. Télécharger la Fiche de Données de Sécurité (FDS / MSDS) Conforme UE', 23);
INSERT INTO products (sku, category_key, name_fr, name_en, subtitle_fr, subtitle_en, inci, cas, origin, extraction_method_fr, extraction_method_en, short_description_fr, short_description_en, image, images, description_fr, specifications_fr, organoleptic_fr, regulatory_fr, quality_fr, confidentiality_fr, sort_order) VALUES ('BNHE007', 'huiles-essentielles', 'Huile Essentielle de Cumin d''Égypte', 'Egyptian Cumin Essential Oil', 'La Chaleur Jaspée – Le Frisson Épicé, Charnel et Mosaïque', 'The Veined Warmth – The Spicy, Carnal and Mosaic Shiver', 'Cuminum Cyminum Seed Oil', '8014-13-9 / 84775-51-9', 'Égypte', 'Distillation complète à la vapeur d''eau des graines séchées et broyées', 'Complete Steam Distillation of Dried and Ground Seeds', 'Distillée à partir des graines de Cuminum cyminum récoltées sous le climat aride et arrosé d''Égypte, notre Huile Essentielle de Cumin de Bostan Naturals est un secret de force et d''audace pour la parfumerie d''auteur. Cet élixir mystique déploie une signature olfactive d''une sensualité troublante et d''une chaleur animale saisissante, hautement recherchée pour les créateurs de niche pour recréer l''atmosphère olfactive de l''Andalousie mauresque. Il se caractérise par une attaque épicée piquante, verte et amère, qui s''épanouit sur un cœur chaud, terreux, charnel et profondément intime (facettes ''peau humaine''), avant de se fondre dans un sillage boisé-balsamique d''une ténacité rare. Un composant d''architecture indispensable pour donner de la sensualité, du relief, de la vibration et un contraste saisissant aux structures Cuirées, Ambrées, et aux notes de Oud de prestige.', 'Distilled from the seeds of Cuminum cyminum harvested under Egypt''s arid and irrigated climate, our Bostan Naturals Cumin Essential Oil is a secret of strength and audacity for author perfumery. This mystical elixir unfolds an olfactory signature of troubling sensuality and striking animal warmth, highly sought after by niche creators to recreate the olfactory atmosphere of Moorish Andalusia. It is characterized by a sharp, green and bitter spicy attack, which blossoms on a warm, earthy, carnal and deeply intimate heart (''human skin'' facets), before melting into a woody-balsamic sillage of rare tenacity. An indispensable architectural component to bring sensuality, relief, vibration and a striking contrast to Leathery, Ambery structures and prestige Oud notes.', '/images/categories/huiles-essentielles.jpg', '[]', 'HUILE ESSENTIELLE DE CUMIN D''ÉGYPTE
La Chaleur Jaspée – Le Frisson Épicé, Charnel et Mosaïque

Distillée à partir des graines de Cuminum cyminum récoltées sous le climat aride et arrosé d''Égypte, notre Huile Essentielle de Cumin de Bostan Naturals est un secret de force et d''audace pour la parfumerie d''auteur. Cet élixir mystique déploie une signature olfactive d''une sensualité troublante et d''une chaleur animale saisissante, hautement recherchée pour les créateurs de niche pour recréer l''atmosphère olfactive de l''Andalousie mauresque. Il se caractérise par une attaque épicée piquante, verte et amère, qui s''épanouit sur un cœur chaud, terreux, charnel et profondément intime (facettes ''peau humaine''), avant de se fondre dans un sillage boisé-balsamique d''une ténacité rare. Un composant d''architecture indispensable pour donner de la sensualité, du relief, de la vibration et un contraste saisissant aux structures Cuirées, Ambrées, et aux notes de Oud de prestige.', '["Nom INCI : Cuminum Cyminum Seed Oil","Numéro CAS : 8014-13-9 / 84775-51-9","Code SKU : BNHE007","Source Botanique : Cuminum cyminum L. (Apiaceae)","Origine : Égypte (100% Pure & Naturelle)","Méthode d''Extraction : Distillation complète à la vapeur d''eau des graines séchées et broyées"]', '["Aspect : Liquide mobile fluide, limpide (pouvant s''épaissir légèrement avec le temps).","Couleur : Jaune clair à ambre-orangé transparent.","Odeur : Très puissante, piquante, intensément épicée, chaude, terreuse, avec une facette animale-charnelle prononcée caractéristique du cumin égyptien authentique.","Indice de Réfraction @ 20°C : 1.4900 – 1.5080","Densité Relative @ 20°C : 0.9050 – 0.9300","Pouvoir Rotatoire @ 20°C : +1.0° à +8.0°","Solubilité : Parfaitement soluble dans l''alcool éthylique et les huiles de support."]', 'Conformité Totale aux Normes Internationales & REACH
Chez Bostan Naturals, l''excellence technique protège votre liberté créative. Notre Huile Essentielle de Cumin est conforme aux exigences et restrictions applicables de l''IFRA pour l''utilisation prévue de la matière en parfumerie (la dernière mise à jour en vigueur) et répond pleinement aux exigences de la réglementation européenne REACH. Pour chaque expédition, nous suivons de près ses constituants naturels restreints (notamment le cuminaldéhyde) afin de garantir une sécurité dermatologique absolue pour la formulation en Catégorie 4 (Fine Fragrances) et d''assurer une traçabilité totale en Europe.', 'Standard de Production : Suivi strict des processus de distillation pour garantir un profil moléculaire constant et stable d''un lot à l''autre, selon les plus strictes directives de management de la qualité.
Authenticité Égyptienne Garantie : Traçabilité totale depuis les cultures locales contrôlées jusqu''au conditionnement final.
Contrôle Laboratoire : Les analyses sont réalisées selon les exigences du produit et du lot, auprès de laboratoires appropriés lorsque nécessaire.
Conditionnement de Transport Conforme aux Exigences Applicables : Expédié dans des conteneurs en aluminium professionnels scellés, assurant une étanchéité parfaite contre l''air et la lumière pour protéger le cuminaldéhyde réactif. Chaque unité est munie d''une étiquette technique standardisée de traçabilité (Sceau Bostan Naturals, SKU, Batch et Mentions légales).', 'Votre Traçabilité Commerciale sous Sceau de Confidentialité :
Pour préserver l''intégrité de vos formules et masquer l''identité de vos fournisseurs stratégiques, Bostan Naturals édite l''intégralité des rapports d''analyses techniques exclusivement sous sa propre marque :
1. Télécharger l''exemple de profil GC-MS (Empreinte chromatographique certifiant la pureté à 100%)
2. Télécharger le Certificat d''Analyse (COA) Spécifique au Lot lié au SKU BNHE007
3. Télécharger la Fiche de Données de Sécurité (FDS / MSDS) Conforme UE', 24);
INSERT INTO products (sku, category_key, name_fr, name_en, subtitle_fr, subtitle_en, inci, cas, origin, extraction_method_fr, extraction_method_en, short_description_fr, short_description_en, image, images, description_fr, specifications_fr, organoleptic_fr, regulatory_fr, quality_fr, confidentiality_fr, sort_order) VALUES ('BNCP001', 'huiles-porteuses', 'Huile de Jojoba Dorée d''Égypte', 'Egyptian Golden Jojoba Oil', 'L''Or Liquide du Désert – La Base Absolue des Parfums de Niche et Attars', 'The Liquid Gold of the Desert – The Absolute Base of Niche Perfumes and Attars', 'Simmondsia Chinensis Seed Oil', '90045-98-0 / 61789-91-1', 'Égypte', 'Première pression à froid, non raffinée', 'First Cold Pressing, Unrefined', 'Obtenue par première pression à froid et non raffinée à partir des graines de Simmondsia chinensis cultivées dans les zones arides d''Égypte, notre Huile de Jojoba Dorée de Bostan Naturals est d''une pureté impériale. Connue techniquement comme une cire liquide moléculaire, elle est totalement inodore et possède une stabilité thermique exceptionnelle qui empêche tout rancissement ou oxydation dans le temps. C''est le médium de prestige et la base porteuse (Carrier Oil) par excellence pour la création de parfums huileux de luxe, d''Attars et de sérums botaniques haut de gamme. Elle fusionne magnifiquement avec les absolus les plus précieux sans jamais altérer ni modifier leurs délicates notes olfactives.', 'Obtained by first cold pressing and unrefined from the seeds of Simmondsia chinensis cultivated in the arid zones of Egypt, our Bostan Naturals Golden Jojoba Oil is of imperial purity. Technically known as a molecular liquid wax, it is totally odorless and possesses exceptional thermal stability that prevents any rancidity or oxidation over time. It is the prestige medium and the carrier oil par excellence for the creation of luxury oil-based perfumes, Attars and high-end botanical serums. It blends beautifully with the most precious absolutes without ever altering or modifying their delicate olfactory notes.', '/images/categories/huiles-porteuses.jpg', '[]', 'HUILE DE JOJOBA DORÉE D''ÉGYPTE
L''Or Liquide du Désert – La Base Absolue des Parfums de Niche et Attars

Obtenue par première pression à froid et non raffinée à partir des graines de Simmondsia chinensis cultivées dans les zones arides d''Égypte, notre Huile de Jojoba Dorée de Bostan Naturals est d''une pureté impériale. Connue techniquement comme une cire liquide moléculaire, elle est totalement inodore et possède une stabilité thermique exceptionnelle qui empêche tout rancissement ou oxydation dans le temps. C''est le médium de prestige et la base porteuse (Carrier Oil) par excellence pour la création de parfums huileux de luxe, d''Attars et de sérums botaniques haut de gamme. Elle fusionne magnifiquement avec les absolus les plus précieux sans jamais altérer ni modifier leurs délicates notes olfactives.', '["Nom INCI : Simmondsia Chinensis Seed Oil","Numéro CAS : 90045-98-0 / 61789-91-1","Code SKU : BNCP001","Source Botanique : Simmondsia chinensis (Link) C.K.Schneid. (Simmondsiaceae)","Origine : Égypte (100% Pure, Naturelle, Première Pression à Froid, Non Raffinée)","Grade : Cosmétique et Parfumerie de Luxe (Premium Flash-Filtered)"]', '["Aspect : Liquide huileux mobile d''une grande clarté.","Couleur : Jaune doré brillant, limpide et lumineux.","Odeur : Quasiment inodore, très légère note de noix caractéristique du jojoba brut non raffiné.","Indice de Réfraction @ 20°C : 1.4650 – 1.4670","Densité Relative @ 20°C : 0.8630 – 0.8730","Indice d''Acide : < 1.0 mg KOH/g","Indice de Péroxyde : < 2.0 meq O2/kg (Garantie de fraîcheur absolue et d''absence d''oxydation)"]', 'Sécurité Moléculaire & Conformité REACH Européenne
Chez Bostan Naturals, la pureté est certifiée. Notre Huile de Jojoba Dorée est exempte de tout additif, conservateur ou solvant chimique. Elle est conforme aux exigences applicables de la réglementation européenne REACH et aux critères de sécurité de l''IFRA pour les applications cutanées directes. Naturellement hypoallergénique et non comédogène, elle offre une tolérance cutanée parfaite pour toutes les formulations de parfumerie huileuse en Catégorie 4 (Fine Fragrances) et produits de soin.', 'Standard de Production : Processus d''extraction mécanique rigoureusement contrôlé pour garantir l''absence totale de traitement thermique, selon les plus strictes directives de management de la qualité.
Authenticité Égyptienne Traçable : Pressée directement à partir de graines locales sélectionnées pour leur maturité idéale.
Contrôle Laboratoire : Les analyses sont réalisées selon les exigences du produit et du lot, auprès de laboratoires appropriés lorsque nécessaire.
Conditionnement de Transport Conforme aux Exigences Applicables : Expédié dans des fûts ou flacons blindés en aluminium/PEHD scellés pour préserver l''intégrité biologique de l''huile durant le transport international. Chaque unité est munie d''une étiquette technique standardisée de traçabilité (Sceau Bostan Naturals, SKU, Batch et Mentions légales).', 'La Protection Intégrale de Vos Secrets Commerciaux :
Pour sécuriser vos formulations et protéger l''indépendance de votre approvisionnement, Bostan Naturals édite toute la documentation réglementaire sous son propre sceau corporatif :
1. Télécharger le Profil d''Acides Gras (Analyse par chromatographie certifiant la pureté)
2. Télécharger le Certificat d''Analyse (COA) Spécifique au Lot lié au SKU BNCP001
3. Télécharger la Fiche de Données de Sécurité (FDS / MSDS) Conforme UE', 25);
INSERT INTO products (sku, category_key, name_fr, name_en, subtitle_fr, subtitle_en, inci, cas, origin, extraction_method_fr, extraction_method_en, short_description_fr, short_description_en, image, images, description_fr, specifications_fr, organoleptic_fr, regulatory_fr, quality_fr, confidentiality_fr, sort_order) VALUES ('BNCP002', 'huiles-porteuses', 'Huile de Nigelle d''Égypte', 'Egyptian Black Seed (Nigella) Oil', 'La Force Ancestrale – L''Huile Active aux Éclats Épicés et Magnétiques', 'The Ancestral Strength – The Active Oil with Spicy and Magnetic Sparks', 'Nigella Sativa Seed Oil', '90064-32-7 / 85116-74-1', 'Égypte', 'Première pression à froid mécanique', 'Mechanical First Cold Pressing', 'Pressée à froid à partir des graines sacrées de Nigella sativa cultivées dans les sols riches d''Égypte, notre Huile de Nigelle de Bostan Naturals est une matière première de caractère pour la parfumerie de niche et la cosmétique haut de gamme. Cet élixir actif et puissant déploie une signature aromatique d''une intensité remarquable, très recherchée pour les compositions inspirées des parfums traditionnels de l''Andalousie et de l''Orient. Elle offre une odeur chaude, piquante et profondément épicée, aux notes de poivre noir et de cumin, s''associant magnifiquement avec les bois sombres, l''ambre et le cuir. Très riche en thymoquinone naturelle, elle est également un ingrédient thérapeutique d''exception pour les huiles de soin capillaires et cutanées de luxe.', 'Cold pressed from the sacred seeds of Nigella sativa cultivated in the rich soils of Egypt, our Bostan Naturals Black Seed Oil is a raw material of character for niche perfumery and high-end cosmetics. This active and powerful elixir unfolds an aromatic signature of remarkable intensity, highly sought after for compositions inspired by the traditional perfumes of Andalusia and the Orient. It offers a warm, sharp and deeply spicy scent, with notes of black pepper and cumin, blending beautifully with dark woods, amber and leather. Very rich in natural thymoquinone, it is also an exceptional therapeutic ingredient for luxury hair and skin care oils.', '/images/categories/huiles-porteuses.jpg', '["/images/products/bncp002-1kg.png","/images/products/bncp002-25kgs.png"]', 'HUILE DE NIGELLE D''ÉGYPTE (CUMIN NOIR)
La Force Ancestrale – L''Huile Active aux Éclats Épicés et Magnétiques

Pressée à froid à partir des graines sacrées de Nigella sativa cultivées dans les sols riches d''Égypte, notre Huile de Nigelle de Bostan Naturals est une matière première de caractère pour la parfumerie de niche et la cosmétique haut de gamme. Cet élixir actif et puissant déploie une signature aromatique d''une intensité remarquable, très recherchée pour les compositions inspirées des parfums traditionnels de l''Andalousie et de l''Orient. Elle offre une odeur chaude, piquante et profondément épicée, aux notes de poivre noir et de cumin, s''associant magnifiquement avec les bois sombres, l''ambre et le cuir. Très riche en thymoquinone naturelle, elle est également un ingrédient thérapeutique d''exception pour les huiles de soin capillaires et cutanées de luxe.', '["Nom INCI : Nigella Sativa Seed Oil","Numéro CAS : 90064-32-7 / 85116-74-1","Code SKU : BNCP002","Source Botanique : Nigella sativa L. (Ranunculaceae)","Origine : Égypte (100% Pure, Naturelle, Première Pression à Froid mécanique)","Grade : Cosmétique et Parfumerie d''Auteur (Ultra-Filtered)"]', '["Aspect : Liquide huileux mobile, limpide.","Couleur : Ambre foncé à brun orangé profond.","Odeur : Puissante, piquante, aromatique, intensément épicée, caractéristique de la nigelle égyptienne brute.","Indice de Réfraction @ 20°C : 1.4680 – 1.4750","Densité Relative @ 20°C : 0.9100 – 0.9300","Teneur en Thymoquinone : Analysée par lot (Garantie d''activité biologique supérieure).","Solubilité : Soluble dans les huiles et les solvants de parfumerie."]', 'Conformité Européenne & Rigueur Moléculaire
Chez Bostan Naturals, la sécurité technique valide vos lancements de produits. Notre Huile de Nigelle est conforme aux exigences applicables du règlement REACH de l''Union Européenne et répond strictement aux exigences de sécurité cutanée. Ses composants volatils naturels (comme la thymoquinone et le p-cymène) sont rigoureusement suivis par nos laboratoires pour assurer une tolérance dermatologique parfaite dans vos formulations cosmétiques ou vos parfums de niche en Catégorie 4 (Fine Fragrances).', 'Standard de Production : Standardisation rigoureuse de la pression mécanique pour éviter l''échauffement de l''huile et préserver ses molécules actives, selon les plus strictes directives de management de la qualité.
Qualité Botanique Garantie : Graines de cumin noir égyptien sélectionnées à la main, garantissant une traçabilité sans faille.
Contrôle Laboratoire : Les analyses sont réalisées selon les exigences du produit et du lot, auprès de laboratoires appropriés lorsque nécessaire.
Conditionnement de Transport Conforme aux Exigences Applicables : Livré en flacons d''aluminium professionnels étanches pour bloquer totalement les rayons UV et préserver la puissance aromatique et médicinale de l''huile. Chaque unité est munie d''une étiquette technique standardisée de traçabilité (Sceau Bostan Naturals, SKU, Batch et Mentions légales).', 'La Garantie de la Confidentialité de Vos Sources :
Afin de protéger vos secrets industriels et de masquer l''identité de vos producteurs originaux, Bostan Naturals publie l''intégralité de la documentation technique sous son identité propre :
1. Télécharger l''analyse GC-MS (Profil des acides gras et dosage de la Thymoquinone)
2. Télécharger le Certificat d''Analyse (COA) Spécifique au Lot lié au SKU BNCP002
3. Télécharger la Fiche de Données de Sécurité (FDS / MSDS) Conforme UE', 26);
INSERT INTO products (sku, category_key, name_fr, name_en, subtitle_fr, subtitle_en, inci, cas, origin, extraction_method_fr, extraction_method_en, short_description_fr, short_description_en, image, images, description_fr, specifications_fr, organoleptic_fr, regulatory_fr, quality_fr, confidentiality_fr, sort_order) VALUES ('BNCP003', 'huiles-porteuses', 'Huile d''Amande Douce d''Égypte', 'Egyptian Sweet Almond Oil', 'La Caresse de Soie – La Base Neutre Ultra-Filtrée des Soins de Luxe', 'The Silk Caress – The Ultra-Filtered Neutral Base of Luxury Care', 'Prunus Amygdalus Dulcis Oil', '8007-69-0 / 90320-37-9', 'Égypte', 'Première pression à froid, ultra-filtrée', 'First Cold Pressing, Ultra-Filtered', 'Pressée à froid à partir des amandes sélectionnées en Égypte et soumise à un processus exclusif de filtration ultra-fine chez Bostan Naturals, notre Huile d''Amande Douce est d''une légèreté et d''une pureté absolues. D''une neutralité olfactive parfaite et d''une fluidité exceptionnelle, elle pénètre instantanément sans laisser de film gras lourd. C''est l''ingrédient de base neutre incontournable pour les laboratoires de niche créant des huiles de massage de prestige, des huiles parfumées pour le corps (Body Oils) et des émulsions cosmétiques haut de gamme. Elle sert de support idéal pour disperser les molécules de parfums fins tout en apportant des propriétés adoucissantes et nourrissantes exceptionnelles.', 'Cold pressed from almonds selected in Egypt and subjected to an exclusive ultra-fine filtration process at Bostan Naturals, our Sweet Almond Oil is of absolute lightness and purity. Of perfect olfactory neutrality and exceptional fluidity, it penetrates instantly without leaving a heavy greasy film. It is the essential neutral base ingredient for niche laboratories creating prestige massage oils, scented body oils and high-end cosmetic emulsions. It serves as an ideal support for dispersing fine perfume molecules while providing exceptional softening and nourishing properties.', '/images/categories/huiles-porteuses.jpg', '[]', 'HUILE D''AMANDE DOUCE D''ÉGYPTE
La Caresse de Soie – La Base Neutre Ultra-Filtrée des Soins de Luxe

Pressée à froid à partir des amandes sélectionnées en Égypte et soumise à un processus exclusif de filtration ultra-fine chez Bostan Naturals, notre Huile d''Amande Douce est d''une légèreté et d''une pureté absolues. D''une neutralité olfactive parfaite et d''une fluidité exceptionnelle, elle pénètre instantanément sans laisser de film gras lourd. C''est l''ingrédient de base neutre incontournable pour les laboratoires de niche créant des huiles de massage de prestige, des huiles parfumées pour le corps (Body Oils) et des émulsions cosmétiques haut de gamme. Elle sert de support idéal pour disperser les molécules de parfums fins tout en apportant des propriétés adoucissantes et nourrissantes exceptionnelles.', '["Nom INCI : Prunus Amygdalus Dulcis Oil","Numéro CAS : 8007-69-0 / 90320-37-9","Code SKU : BNCP003","Source Botanique : Prunus amygdalus dulcis (Rosaceae)","Origine : Égypte (100% Pure, Première Pression à Froid, Ultra-Filtrée)","Grade : Cosmétique de Luxe et Parfumerie (Ultra-Light / Neutral Odor)"]', '["Aspect : Liquide huileux mobile, d''une limpidité cristalline parfaite.","Couleur : Jaune très pâle à presque incolore grâce au procédé de filtration fine.","Odeur : Neutre, odeur extrêmement légère et douce d''amande fraîche, sans aucune note rance.","Indice de Réfraction @ 20°C : 1.4670 – 1.4730","Densité Relative @ 20°C : 0.9110 – 0.9200","Indice d''Acide : < 0.5 mg KOH/g","Indice de Péroxyde : < 1.5 meq O2/kg (Garantie de stabilité maximale à long terme)","Solubilité : Miscible dans toutes les proportions avec les autres huiles végétales et solvants de parfumerie."]', 'Sécurité Dermatologique & Conformité REACH
Chez Bostan Naturals, la sécurité de vos clients est notre priorité. Notre Huile d''Amande Douce Ultra-Filtrée est produite sans OGM et sans solvants chimiques, et est conforme aux exigences applicables du règlement REACH de l''Union Européenne. Sa pureté moléculaire élimine les impuretés allergènes, offrant un support neutre, dermatologiquement irréprochable et totalement sûr pour la formulation de produits corporels de luxe et d''applications en Catégorie 4 (Fine Fragrances).', 'Standard de Production : Contrôle strict du cycle de pression et du système de filtration fine pour assurer une fluidité et une neutralité constantes, selon les plus strictes directives de management de la qualité.
Traçabilité Amont Garantie : Sélection des meilleures cultures d''amandiers locaux pour une traçabilité totale.
Contrôle Laboratoire : Les analyses sont réalisées selon les exigences du produit et du lot, auprès de laboratoires appropriés lorsque nécessaire.
Conditionnement de Transport Conforme aux Exigences Applicables : Conditionné sous atmosphère protectrice en fûts d''aluminium blindés scellés, bloquant l''oxygène pour garantir une durée de conservation exceptionnelle sans rancissement. Chaque unité est munie d''une étiquette technique standardisée de traçabilité (Sceau Bostan Naturals, SKU, Batch et Mentions légales).', 'Votre Sécurité Commerciale sous Sceau de Confidentialité :
Pour garantir le secret absolu de vos approvisionnements stratégiques et la traçabilité légale de vos intrants, Bostan Naturals publie toute la documentation technique sous sa propre marque :
1. Télécharger le Profil d''Acides Gras (Analyse GC certifiant l''authenticité et la pureté)
2. Télécharger le Certificat d''Analyse (COA) Spécifique au Lot lié au SKU BNCP003
3. Télécharger la Fiche de Données de Sécurité (FDS / MSDS) Conforme UE', 27);
INSERT INTO products (sku, category_key, name_fr, name_en, subtitle_fr, subtitle_en, inci, cas, origin, extraction_method_fr, extraction_method_en, short_description_fr, short_description_en, image, images, description_fr, specifications_fr, organoleptic_fr, regulatory_fr, quality_fr, confidentiality_fr, sort_order) VALUES ('BNCP004', 'huiles-porteuses', 'Huile de Pépins de Grenade d''Égypte', 'Egyptian Pomegranate Seed Oil', 'Le Joyau Anti-Âge Ultime – La Base Précieuse et Active des Soins de Prestige', 'The Ultimate Anti-Aging Jewel – The Precious Active Base of Prestige Care', 'Punica Granatum Seed Oil', '84961-57-9', 'Égypte', 'Première pression à froid mécanique, non raffinée', 'Mechanical First Cold Pressing, Unrefined', 'Obtenue par première pression à froid mécanique des pépins de grenades mûries sous le soleil d''Égypte, notre Huile de Pépins de Grenade de Bostan Naturals est une matière première d''exception pour la cosmétique haut de gamme et les élixirs cutanés de luxe. Ce joyau lipidique rare est exceptionnellement riche en acide punicique (un acide gras conjugué rare oméga-5), réputé mondialement pour ses propriétés antioxydantes, régénérantes et anti-âge hors du commun. D''une texture onctueuse et enveloppante, elle sert de base active royale (Carrier Oil) pour les laboratoires de niche créant des sérums faciaux haut de gamme, des huiles de massage impériales et des soins corporels réparateurs haut de gamme, offrant une régénération cellulaire intense et un fini satiné parfait.', 'Obtained by mechanical first cold pressing of pomegranate seeds ripened under the Egyptian sun, our Bostan Naturals Pomegranate Seed Oil is an exceptional raw material for high-end cosmetics and luxury skin elixirs. This rare lipid jewel is exceptionally rich in punicic acid (a rare conjugated omega-5 fatty acid), world-renowned for its extraordinary antioxidant, regenerating and anti-aging properties. With a smooth and enveloping texture, it serves as an active royal carrier oil for niche laboratories creating high-end facial serums, imperial massage oils and high-end reparative body care, offering intense cellular regeneration and a perfect satin finish.', '/images/categories/huiles-porteuses.jpg', '[]', 'HUILE DE PÉPINS DE GRENADE D''ÉGYPTE
Le Joyau Anti-Âge Ultime – La Base Précieuse et Active des Soins de Prestige

Obtenue par première pression à froid mécanique des pépins de grenades mûries sous le soleil d''Égypte, notre Huile de Pépins de Grenade de Bostan Naturals est une matière première d''exception pour la cosmétique haut de gamme et les élixirs cutanés de luxe. Ce joyau lipidique rare est exceptionnellement riche en acide punicique (un acide gras conjugué rare oméga-5), réputé mondialement pour ses propriétés antioxydantes, régénérantes et anti-âge hors du commun. D''une texture onctueuse et enveloppante, elle sert de base active royale (Carrier Oil) pour les laboratoires de niche créant des sérums faciaux haut de gamme, des huiles de massage impériales et des soins corporels réparateurs haut de gamme, offrant une régénération cellulaire intense et un fini satiné parfait.', '["Nom INCI : Punica Granatum Seed Oil","Numéro CAS : 84961-57-9","Code SKU : BNCP004","Source Botanique : Punica granatum L. (Punicaceae)","Origine : Égypte (100% Pure, Naturelle, Première Pression à Froid mécanique, Non Raffinée)","Grade : Cosmétique Active de Luxe (Premium Flash-Filtered)"]', '["Aspect : Liquide huileux moyennement visqueux, limpide.","Couleur : Jaune d''or brillant à ambré clair transparent.","Odeur : Caractéristique légère, douce, subtilement fruitée-acide, sans aucune note rance.","Indice de Réfraction @ 20°C : 1.5150 – 1.5250 (Haute valeur due à l''acide punicique conjugué)","Densité Relative @ 20°C : 0.9350 – 0.9500","Teneur en Acide Punicique (Oméga-5) : > 70.0% (Garantie d''authenticité et d''efficacité biologique)","Indice de Péroxyde : < 5.0 meq O2/kg","Solubilité : Miscible avec les huiles végétales et les solvants lipophiles."]', 'Sécurité Dermatologique Certifiée & REACH
Chez Bostan Naturals, la pureté est indiscutable. Notre Huile de Pépins de Grenade est produite sans solvants chimiques ajoutés et sans conservateurs, et est conforme aux exigences applicables du règlement REACH de l''Union Européenne. Naturellement apaisante et hautement protectrice pour la barrière cutanée, elle offre une sécurité d''utilisation dermatologique absolue et un support actif idéal pour toutes les formulations de soins cosmétiques haut de gamme et d''applications en Catégorie 4.', 'Standard de Production : Processus d''extraction mécanique contrôlé sous température régulée pour éviter toute dégradation de l''acide punicique thermosensible, selon les plus strictes directives de management de la qualité.
Approvisionnement Durable Garanti : Issu exclusivement de pépins de grenades locales rigoureusement sélectionnées après pressage des jus.
Contrôle Laboratoire : Les analyses sont réalisées selon les exigences du produit et du lot, auprès de laboratoires appropriés lorsque nécessaire.
Conditionnement de Transport Conforme aux Exigences Applicables : Conditionné sous atmosphère inerte (azote) en fûts d''aluminium ou de PEHD blindés étanches, bloquant totalement l''oxygène pour garantir une conservation optimale de ses propriétés actives. Chaque unité est munie d''une étiquette technique standardisée de traçabilité (Sceau Bostan Naturals, SKU, Batch et Mentions légales).', 'La Protection Intégrale de Vos Secrets Commerciaux :
Pour sécuriser vos formulations et protéger l''indépendance de votre approvisionnement, Bostan Naturals édite toute la documentation réglementaire sous son propre sceau corporatif :
1. Télécharger le Profil d''Acides Gras (Analyse par chromatographie certifiant le taux d''Oméga-5)
2. Télécharger le Certificat d''Analyse (COA) Spécifique au Lot lié au SKU BNCP004
3. Télécharger la Fiche de Données de Sécurité (FDS / MSDS) Conforme UE', 28);
INSERT INTO products (sku, category_key, name_fr, name_en, subtitle_fr, subtitle_en, inci, cas, origin, extraction_method_fr, extraction_method_en, short_description_fr, short_description_en, image, images, description_fr, specifications_fr, organoleptic_fr, regulatory_fr, quality_fr, confidentiality_fr, sort_order) VALUES ('BNCP005', 'huiles-porteuses', 'Huile de Pépins de Courge d''Égypte', 'Egyptian Pumpkin Seed Oil', 'Le Bouclier Vert-Or – La Matrice Dense et Active des Soins Masculins et Attars', 'The Green-Gold Shield – The Dense Active Matrix of Men''s Care and Attars', 'Cucurbita Pepo Seed Oil', '8016-49-7 / 89998-03-3', 'Égypte', 'Première pression à froid mécanique, non raffinée', 'Mechanical First Cold Pressing, Unrefined', 'Obtenue par première pression à froid mécanique des pépins sélectionnées de courge mûries sous le climat généreux d''Égypte, notre Huile de Pépins de Courge de Bostan Naturals est une matière première de prestige pour la cosmétique haut de gamme et les soins capillaires de luxe. Ce joyau lipidique est exceptionnellement riche en phytostérols, en zinc et en acides gras essentiels (Oméga-6 et 9), réputés mondialement pour leurs propriétés fortifiantes, régénérantes et protectrices du bulbe capillaire. D''une texture onctueuse et fluide, elle déploie une très légère note de noix grillée qui s''associe magnifiquement avec les compositions masculines et les notes boisées-sombres des Attars, offrant une base active royale (Carrier Oil) pour les laboratoires de niche créant des huiles de barbe de prestige, des sérums anti-chute et des soins corporels haut de gamme.', 'Obtained by mechanical first cold pressing of selected pumpkin seeds ripened under Egypt''s generous climate, our Bostan Naturals Pumpkin Seed Oil is a prestige raw material for high-end cosmetics and luxury hair care. This lipid jewel is exceptionally rich in phytosterols, zinc and essential fatty acids (Omega-6 and 9), world-renowned for their strengthening, regenerating and hair bulb protecting properties. With a smooth and fluid texture, it deploys a very slight toasted nut note that blends magnificently with masculine compositions and the dark woody notes of Attars, offering an active royal carrier oil for niche laboratories creating prestige beard oils, anti-hair loss serums and high-end body care.', '/images/categories/huiles-porteuses.jpg', '[]', 'HUILE DE PÉPINS DE COURGE D''ÉGYPTE (CITROUILLE)
Le Bouclier Vert-Or – La Matrice Dense et Active des Soins Masculins et Attars

Obtenue par première pression à froid mécanique des pépins sélectionnées de courge mûries sous le climat généreux d''Égypte, notre Huile de Pépins de Courge de Bostan Naturals est une matière première de prestige pour la cosmétique haut de gamme et les soins capillaires de luxe. Ce joyau lipidique est exceptionnellement riche en phytostérols, en zinc et en acides gras essentiels (Oméga-6 et 9), réputés mondialement pour leurs propriétés fortifiantes, régénérantes et protectrices du bulbe capillaire. D''une texture onctueuse et fluide, elle déploie une très légère note de noix grillée qui s''associe magnifiquement avec les compositions masculines et les notes boisées-sombres des Attars, offrant une base active royale (Carrier Oil) pour les laboratoires de niche créant des huiles de barbe de prestige, des sérums anti-chute et des soins corporels haut de gamme.', '["Nom INCI : Cucurbita Pepo Seed Oil","Numéro CAS : 8016-49-7 / 89998-03-3","Code SKU : BNCP005","Source Botanique : Cucurbita pepo L. (Cucurbitaceae)","Origine : Égypte (100% Pure, Naturelle, Première Pression à Froid mécanique, Non Raffinée)","Grade : Cosmétique Active et Parfumerie d''Auteur (Premium Ultra-Filtered)"]', '["Aspect : Liquide huileux mobile, limpide et brillant.","Couleur : Jaune doré profond à reflets vert-olive transparents (effet dichromatique naturel).","Odeur : Subtile, douce, de noix fraîche et de graine séchée, sans aucune note rance.","Indice de Réfraction @ 20°C : 1.4700 – 1.4760","Densité Relative @ 20°C : 0.9150 – 0.9250","Indice d''Acide : < 1.5 mg KOH/g","Indice de Péroxyde : < 4.0 meq O2/kg (Garantie de fraîcheur absolue et d''absence d''oxydation)","Solubilité : Miscible avec les huiles végétales et les solvants lipophiles de parfumerie."]', 'Sécurité Moléculaire & Conformité REACH Européenne
Chez Bostan Naturals, la pureté est indiscutable. Notre Huile de Pépins de Courge est produite sans solvants chimiques ajoutés et sans conservateurs, et est conforme aux exigences applicables du règlement REACH de l''Union Européenne. Naturellement apaisante et hautement protectrice pour la barrière cutanée et le cuir chevelu, elle offre une sécurité d''utilisation dermatologique absolue et un support actif idéal pour toutes les formulations de soins cosmétiques haut de gamme masculins et d''applications en Catégorie 4 (Fine Fragrances).', 'Standard de Production : Processus d''extraction mécanique contrôlé sous température régulée pour éviter toute dénaturation des phytostérols thermosensibles, selon les plus strictes directives de management de la qualité.
Approvisionnement Durable Garanti : Issu exclusivement de pépins de courges locales rigoureusement lavés, séchés et triés après récolte.
Contrôle Laboratoire : Les analyses sont réalisées selon les exigences du produit et du lot, auprès de laboratoires appropriés lorsque nécessaire.
Conditionnement de Transport Conforme aux Exigences Applicables : Conditionné sous atmosphère inerte (azote) en flacons ou fûts d''aluminium blindés étanches, bloquant totalement l''oxygène pour garantir une conservation optimale de ses propriétés actives. Chaque unité est munie d''une étiquette technique standardisée de traçabilité (Sceau Bostan Naturals, SKU, Batch et Mentions légales).', 'La Protection Intégrale de Vos Secrets Commerciaux :
Pour sécuriser vos formulations et protéger l''indépendance de votre approvisionnement, Bostan Naturals édite toute la documentation réglementaire sous son propre sceau corporatif :
1. Télécharger le Profil d''Acides Gras (Analyse par chromatographie certifiant la pureté)
2. Télécharger le Certificat d''Analyse (COA) Spécifique au Lot lié au SKU BNCP005
3. Télécharger la Fiche de Données de Sécurité (FDS / MSDS) Conforme UE', 29);